CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `fza_caja_depositos_view` AS select 'ALTA' AS `ROL_EN_OPERACION`,`d`.`ID_DEPOSITO_DEP` AS `ID_DEPOSITO_DEP`,`d`.`CODIGO_EMP_DEP` AS `CODIGO_EMPRESA_OP`,`d`.`CODIGO_ALM_DEP` AS `CODIGO_ALMACEN_OP`,`d`.`CODIGO_CAJA_DEP` AS `CODIGO_CAJA_OP`,`d`.`NUMERO_OPERACION_DEP` AS `NUMERO_OPERACION_OP`,`d`.`CODIGO_CLI_DEP` AS `CODIGO_CLI_DEP`,`d`.`CODIGO_ART_DEP` AS `CODIGO_ART_DEP`,`d`.`CODIGO_UNIDAD_DEP` AS `CODIGO_UNIDAD_DEP`,`d`.`CODIGO_ALM_DEP` AS `CODIGO_ALM_DEP`,`d`.`CANTIDAD_PENDIENTE_DEP` AS `CANTIDAD_PENDIENTE_DEP`,`d`.`PRECIO_VENTA_DEP` AS `PRECIO_VENTA_DEP`,`d`.`PORCENTAJE_IVA_DEP` AS `PORCENTAJE_IVA_DEP`,`d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_ANTICIPO_DEP`,`d`.`PRECIO_VENTA_DEP` - `d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_PENDIENTE_DEP`,`d`.`ESTADO_DEP` AS `ESTADO_DEP`,`d`.`FECHA_CREACION_DEP` AS `FECHA_CREACION_DEP`,`d`.`FECHA_ENTREGA_DEP` AS `FECHA_ENTREGA_DEP`,`d`.`EMPRESA_CANCEL_DEP` AS `EMPRESA_CANCEL_DEP`,`d`.`ALMACEN_CANCEL_DEP` AS `ALMACEN_CANCEL_DEP`,`d`.`CAJA_CANCEL_DEP` AS `CAJA_CANCEL_DEP`,`d`.`NUMERO_OPERACION_CANCEL_DEP` AS `NUMERO_OPERACION_CANCEL_DEP` from `fza_depositos_cliente` `d` where `d`.`NUMERO_OPERACION_DEP` is not null and `d`.`NUMERO_OPERACION_DEP` <> '' union all select 'CANCELACION' AS `ROL_EN_OPERACION`,`d`.`ID_DEPOSITO_DEP` AS `ID_DEPOSITO_DEP`,`d`.`EMPRESA_CANCEL_DEP` AS `CODIGO_EMPRESA_OP`,`d`.`ALMACEN_CANCEL_DEP` AS `CODIGO_ALMACEN_OP`,`d`.`CAJA_CANCEL_DEP` AS `CODIGO_CAJA_OP`,`d`.`NUMERO_OPERACION_CANCEL_DEP` AS `NUMERO_OPERACION_OP`,`d`.`CODIGO_CLI_DEP` AS `CODIGO_CLI_DEP`,`d`.`CODIGO_ART_DEP` AS `CODIGO_ART_DEP`,`d`.`CODIGO_UNIDAD_DEP` AS `CODIGO_UNIDAD_DEP`,`d`.`CODIGO_ALM_DEP` AS `CODIGO_ALM_DEP`,`d`.`CANTIDAD_PENDIENTE_DEP` AS `CANTIDAD_PENDIENTE_DEP`,`d`.`PRECIO_VENTA_DEP` AS `PRECIO_VENTA_DEP`,`d`.`PORCENTAJE_IVA_DEP` AS `PORCENTAJE_IVA_DEP`,`d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_ANTICIPO_DEP`,`d`.`PRECIO_VENTA_DEP` - `d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_PENDIENTE_DEP`,`d`.`ESTADO_DEP` AS `ESTADO_DEP`,`d`.`FECHA_CREACION_DEP` AS `FECHA_CREACION_DEP`,`d`.`FECHA_ENTREGA_DEP` AS `FECHA_ENTREGA_DEP`,`d`.`EMPRESA_CANCEL_DEP` AS `EMPRESA_CANCEL_DEP`,`d`.`ALMACEN_CANCEL_DEP` AS `ALMACEN_CANCEL_DEP`,`d`.`CAJA_CANCEL_DEP` AS `CAJA_CANCEL_DEP`,`d`.`NUMERO_OPERACION_CANCEL_DEP` AS `NUMERO_OPERACION_CANCEL_DEP` from `fza_depositos_cliente` `d` where `d`.`NUMERO_OPERACION_CANCEL_DEP` is not null and `d`.`NUMERO_OPERACION_CANCEL_DEP` <> '' union all select case `o`.`TIPO_OPERACION_OPCAJA` when 'DE' then 'COBRO_INICIAL' when 'CB' then 'COBRO_PARCIAL' end AS `ROL_EN_OPERACION`,`d`.`ID_DEPOSITO_DEP` AS `ID_DEPOSITO_DEP`,`o`.`CODIGO_EMP_OPCAJA` AS `CODIGO_EMPRESA_OP`,`o`.`CODIGO_ALM_OPCAJA` AS `CODIGO_ALMACEN_OP`,`o`.`CODIGO_CAJA_OPCAJA` AS `CODIGO_CAJA_OP`,`o`.`NUMERO_OPERACION_OPCAJA` AS `NUMERO_OPERACION_OP`,`d`.`CODIGO_CLI_DEP` AS `CODIGO_CLI_DEP`,`d`.`CODIGO_ART_DEP` AS `CODIGO_ART_DEP`,`d`.`CODIGO_UNIDAD_DEP` AS `CODIGO_UNIDAD_DEP`,`d`.`CODIGO_ALM_DEP` AS `CODIGO_ALM_DEP`,`d`.`CANTIDAD_PENDIENTE_DEP` AS `CANTIDAD_PENDIENTE_DEP`,`d`.`PRECIO_VENTA_DEP` AS `PRECIO_VENTA_DEP`,`d`.`PORCENTAJE_IVA_DEP` AS `PORCENTAJE_IVA_DEP`,`d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_ANTICIPO_DEP`,`d`.`PRECIO_VENTA_DEP` - `d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_PENDIENTE_DEP`,`d`.`ESTADO_DEP` AS `ESTADO_DEP`,`d`.`FECHA_CREACION_DEP` AS `FECHA_CREACION_DEP`,`d`.`FECHA_ENTREGA_DEP` AS `FECHA_ENTREGA_DEP`,`d`.`EMPRESA_CANCEL_DEP` AS `EMPRESA_CANCEL_DEP`,`d`.`ALMACEN_CANCEL_DEP` AS `ALMACEN_CANCEL_DEP`,`d`.`CAJA_CANCEL_DEP` AS `CAJA_CANCEL_DEP`,`d`.`NUMERO_OPERACION_CANCEL_DEP` AS `NUMERO_OPERACION_CANCEL_DEP` from (`fza_caja_operaciones` `o` join `fza_depositos_cliente` `d` on(`d`.`ID_DEPOSITO_DEP` = `o`.`ID_DEPOSITO_OPCAJA`)) where `o`.`TIPO_OPERACION_OPCAJA` in ('CB','DE') and `o`.`ID_DEPOSITO_OPCAJA` is not null;

-- Vista: v_articulos_stock_barras
DROP TABLE IF EXISTS `v_articulos_stock_barras`;
DROP VIEW IF EXISTS `v_articulos_stock_barras`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_articulos_stock_barras` AS select coalesce(`s`.`CODIGO_UNIDAD_SKU`,`a`.`CODIGO_ART_ART`) AS `SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`cb`.`CODIGO_BARRAS_CB` AS `CODIGO_BARRAS`,coalesce(sum(`stk`.`CANTIDAD_STK`),0) AS `STOCK_TOTAL` from (((`fza_articulos` `a` left join `fza_articulos_skus` `s` on(`a`.`CODIGO_ART_ART` = `s`.`CODIGO_ART_SKU`)) left join `fza_codigos_barras` `cb` on(`cb`.`CODIGO_UNIDAD_CB` = coalesce(`s`.`CODIGO_UNIDAD_SKU`,`a`.`CODIGO_ART_ART`))) left join `fza_articulos_stockactual` `stk` on(`stk`.`CODIGO_UNIDAD_STK` = coalesce(`s`.`CODIGO_UNIDAD_SKU`,`a`.`CODIGO_ART_ART`))) group by coalesce(`s`.`CODIGO_UNIDAD_SKU`,`a`.`CODIGO_ART_ART`),`a`.`DESCRIPCION_ART`,`cb`.`CODIGO_BARRAS_CB`;

