USUARIO_ALTA`,`a`.`USUARIO_MODIF` AS `USUARIO_MODIF`,`prv`.`NOMBRE_PRV` AS `NOMBRE_PRV_ALBC`,`emp`.`RAZON_SOCIAL_EMP` AS `RAZON_SOCIAL_EMPRESA_VIEW_ALBC`,`tp`.`PV` AS `TEMPORADA_ALBC`,`a`.`FECHA_ALBC` AS `FECHA_REALIZACION_ALBC`,`a`.`FECHA_ALBC` AS `FECHA_EFECTO_STOCK_ALBC`,`p`.`FECHA_TOPE_RECEPCION_PEDC` AS `FECHA_TOPE_RECEPCION_ALBC`,coalesce(`r`.`TOTAL_PRENDAS_ALBC`,0) AS `TOTAL_PRENDAS_ALBC`,coalesce(`r`.`TOTAL_LINEAS_ALBC`,0) AS `TOTAL_LINEAS_ALBC` from (((((`fza_albaranes_compra` `a` left join `fza_proveedores` `prv` on(`prv`.`CODIGO_PRV_PRV` = `a`.`CODIGO_PRV_ALBC`)) left join `fza_empresas` `emp` on(`emp`.`CODIGO_EMP_EMP` = `a`.`CODIGO_EMP_ALBC`)) left join `fza_pedidos_compra` `p` on(`p`.`SERIE_PEDC` = `a`.`SERIE_PED_ALBC` and `p`.`NUMERO_PEDC` = `a`.`NUMERO_PED_ALBC`)) left join `fza_propiedades_valores` `tp` on(`tp`.`ID_PV_ARTPROP` = `p`.`ID_PV_TEMPORADA_PEDC` and `tp`.`ID_PROP_PV` = 'TEMPORADA')) left join (select `l`.`SERIE_ALBC_ALBCLIN` AS `SERIE_ALBC_ALBCLIN`,`l`.`NUMERO_ALBC_ALBCLIN` AS `NUMERO_ALBC_ALBCLIN`,coalesce(sum(coalesce(`l`.`TOTAL_UNIDADES_ALBCLIN`,`l`.`CANTIDAD_ALBCLIN`,0)),0) AS `TOTAL_PRENDAS_ALBC`,coalesce(sum(`l`.`TOTAL_ALBCLIN`),0) AS `TOTAL_LINEAS_ALBC` from `fza_albaranes_compra_lineas` `l` group by `l`.`SERIE_ALBC_ALBCLIN`,`l`.`NUMERO_ALBC_ALBCLIN`) `r` on(`r`.`SERIE_ALBC_ALBCLIN` = `a`.`SERIE_ALBC` and `r`.`NUMERO_ALBC_ALBCLIN` = `a`.`NUMERO_ALBC`));

