CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_art_busquedas` AS select `a`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,`a`.`ESACTIVO_ART` AS `ESACTIVO_ART`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`af`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`p`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PROVEEDOR`,`ap`.`REF_PROVEEDOR_AP` AS `REF_PROVEEDOR`,`ap`.`ESPROVEEDORPRINCIPAL_AP` AS `ESPROVEEDORPRINCIPAL`,`ap`.`PRECIO_ULT_COMPRA_AP` AS `PRECIO_ULT_COMPRA`,`at2`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR`,`t`.`NOMBRE_TAR_TAR` AS `NOMBRE_TAR_TAR`,`at2`.`PRECIO_SALIDA_ARTTAR` AS `PRECIO_SALIDA_ARTTAR`,`at2`.`PRECIO_DTO_ARTTAR` AS `PRECIO_DTO_ARTTAR`,`at2`.`PORCENTAJE_DTO_ARTTAR` AS `PORCENTAJE_DTO_ARTTAR`,`at2`.`PRECIO_FINAL_ARTTAR` AS `PRECIO_FINAL_ARTTAR`,`at2`.`FECHA_DESDE_ARTTAR` AS `FECHA_DESDE_ARTTAR`,`at2`.`FECHA_HASTA_ARTTAR` AS `FECHA_HASTA_ARTTAR`,`t`.`ESIMP_INCL_TAR` AS `ESIMP_INCL_TAR`,`iv`.`NOMBRE_TIPO_IVA_IVATIP` AS `NOMBRE_TIPO_IVA_IVATIP`,`a`.`TIPO_IVA_ART` AS `TIPO_IVA_ART`,`a`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`a`.`USUARIO_MODIF` AS `USUARIO_MODIF`,`a`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`a`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`a`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`a`.`ESACTIVO_FIJO_ART` AS `ESACTIVO_FIJO_ART` from ((((((`fza_articulos` `a` left join `fza_articulos_familias` `af` on(`af`.`CODIGO_FAM_FAM` = `a`.`CODIGO_FAM_ART`)) left join `fza_articulos_tarifas` `at2` on(`at2`.`CODIGO_ART_ARTTAR` = `a`.`CODIGO_ART_ART` and ifnull(`at2`.`CODIGO_UNIDAD_ARTTAR`,'') = '' and `at2`.`ESACTIVO_ARTTAR` = 'S')) left join `fza_tarifas` `t` on(`t`.`CODIGO_TAR_ARTTAR` = `at2`.`CODIGO_TAR_ARTTAR` and `t`.`ESACTIVO_ARTTAR` = 'S' and `t`.`ORDEN_TAR` = (select min(`t2`.`ORDEN_TAR`) from `fza_tarifas` `t2` where `t2`.`ESACTIVO_ARTTAR` = 'S'))) left join `fza_ivas_tipos` `iv` on(`iv`.`CODIGO_ABREVIATURA_IVA_IVATIP` = `a`.`TIPO_IVA_ART`)) left join `fza_articulos_proveedores` `ap` on(`ap`.`CODIGO_ART_AP` = `a`.`CODIGO_ART_ART` and `ap`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` `p` on(`p`.`CODIGO_PRV_PRV` = `ap`.`CODIGO_PRV_AP`)) where `a`.`ESACTIVO_ART` = 'S' order by `a`.`ORDEN_ART`;

-- Vista: vi_articulos
DROP TABLE IF EXISTS `vi_articulos`;
DROP VIEW IF EXISTS `vi_articulos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos` AS select `art`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,`art`.`ESACTIVO_ART` AS `ESACTIVO_ART`,`art`.`ESWEB_ART` AS `ESWEB_ART`,`art`.`ORDEN_ART` AS `ORDEN_ART`,`art`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`art`.`ESVARIACION_ART` AS `ESVARIACION_ART`,`art`.`ESTRAZABLE_ART` AS `ESTRAZABLE_ART`,`art`.`TIPO_ART` AS `TIPO_ART`,`art`.`TIPO_VARIACION_ART` AS `TIPO_VARIACION_ART`,`art`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`fam`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`fam`.`NOMBRE_FAM_FAM` AS `NOMBRE_FAM_FAM`,`art`.`TIPO_IVA_ART` AS `TIPO_IVA_ART`,`iva`.`NOMBRE_TIPO_IVA_IVATIP` AS `NOMBRE_TIPO_IVA_IVATIP`,`art`.`ESACTIVO_FIJO_ART` AS `ESACTIVO_FIJO_ART`,`art`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_AP`,`prv`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`prv`.`NOMBRE_PRV` AS `NOMBRE_PRV`,`ap`.`REF_PROVEEDOR_AP` AS `REF_PROVEEDOR`,coalesce(`pv`.`PV`,`atemp`.`VALOR_LIBRE_ARTPROP`) AS `TEMPORADA_ART`,`art`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`art`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`art`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`art`.`USUARIO_MODIF` AS `USUARIO_MODIF` from ((((((`fza_articulos` `art` left join `fza_articulos_familias` `fam` on(`art`.`CODIGO_FAM_ART` = `fam`.`CODIGO_FAM_FAM`)) left join `fza_articulos_proveedores` `ap` on(`art`.`CODIGO_ART_ART` = `ap`.`CODIGO_ART_AP` and `ap`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` `prv` on(`ap`.`CODIGO_PRV_AP` = `prv`.`CODIGO_PRV_PRV`)) left join `fza_ivas_tipos` `iva` on(`art`.`TIPO_IVA_ART` = `iva`.`CODIGO_ABREVIATURA_IVA_IVATIP`)) left join `fza_articulos_propiedades` `atemp` on(`art`.`CODIGO_ART_ART` = `atemp`.`CODIGO_ART_ART` and `atemp`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA')) left join `fza_propiedades_valores` `pv` on(`atemp`.`ID_PV_ARTPROP` = `pv`.`ID_PV_ARTPROP`)) order by `art`.`ORDEN_ART`;

-- Vista: vi_articulos_conjuntos_slots
DROP TABLE IF EXISTS `vi_articulos_conjuntos_slots`;
DROP VIEW IF EXISTS `vi_articulos_conjuntos_slots`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_conjuntos_slots` AS select `a`.`CODIGO_ART_ART` AS `CODIGO_ART_ACA`,`a`.`TIPO_VARIACION_ART` AS `ID_VAR_AC`,`va`.`ID_ATB_VA` AS `ID_VA_ACA`,coalesce(`va`.`NOMBRE_VA`,`va`.`ID_ATB_VA`) AS `NOMBRE_ATRIBUTO`,`va`.`ORDEN_VA` AS `ORDEN_ATRIBUTO`,`v`.`NOMBRE_VAR` AS `NOMBRE_VARIACION`,`aca`.`ID_AC_ACA` AS `ID_AC_ACA`,`ac`.`NOMBRE_AC` AS `NOMBRE_AC`,`ac`.`ID_VA_AC` AS `ID_VA_AC`,coalesce(`aca`.`ESGENERACION_AUTO_ACA`,'S') AS `ESGENERACION_AUTO_ACA`,`aca`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`aca`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`aca`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`aca`.`USUARIO_MODIF` AS `USUARIO_MODIF` from ((((`fza_articulos` `a` join `fza_variaciones_atributos` `va` on(`va`.`ID_VAR_VA` = `a`.`TIPO_VARIACION_ART`)) join `fza_variaciones` `v` on(`v`.`CODIGO_VAR` = `a`.`TIPO_VARIACION_ART`)) left join `fza_articulos_conjuntos_asign` `aca` on(`aca`.`CODIGO_ART_ACA` = `a`.`CODIGO_ART_ART` and `aca`.`ID_VA_ACA` = `va`.`ID_ATB_VA`)) left join `fza_atributos_conjuntos` `ac` on(`ac`.`ID_AC` = `aca`.`ID_AC_ACA`)) where `a`.`ESVARIACION_ART` = 'S' and `a`.`TIPO_VARIACION_ART` is not null order by `a`.`CODIGO_ART_ART`,`va`.`ORDEN_VA`;

-- Vista: vi_articulos_familias
DROP TABLE IF EXISTS `vi_articulos_familias`;
DROP VIEW IF EXISTS `vi_articulos_familias`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_familias` AS select `fza_articulos_familias`.`CODIGO_FAM_FAM` AS `CODIGO_FAM_FAM`,`fza_articulos_familias`.`ESACTIVO_FAM` AS `ESACTIVO_FAM`,`fza_articulos_familias`.`ORDEN_FAM` AS `ORDEN_FAM`,`fza_articulos_familias`.`ESDEFAULT_FAM` AS `ESDEFAULT_FAM`,`fza_articulos_familias`.`CODIGO_SUBFAMILIA_FAM` AS `CODIGO_SUBFAMILIA_FAM`,`fza_articulos_familias2`.`NOMBRE_FAM_FAM` AS `NOMBRE_SUBFAMILIA`,`fza_articulos_familias`.`NOMBRE_FAM_FAM` AS `NOMBRE_FAM_FAM`,`fza_articulos_familias`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`fza_articulos_familias`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_articulos_familias`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_articulos_familias`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_articulos_familias`.`USUARIO_MODIF` AS `USUARIO_MODIF` from (`fza_articulos_familias` left join `fza_articulos_familias` `fza_articulos_familias2` on(`fza_articulos_familias`.`CODIGO_SUBFAMILIA_FAM` = `fza_articulos_familias2`.`CODIGO_FAM_FAM`)) order by `fza_articulos_familias`.`ORDEN_FAM`;

-- Vista: vi_articulos_familias_list
DROP TABLE IF EXISTS `vi_articulos_familias_list`;
DROP VIEW IF EXISTS `vi_articulos_familias_list`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_familias_list` AS select `fza_articulos_familias`.`CODIGO_FAM_FAM` AS `CODIGO_FAM_FAM`,`fza_articulos_familias`.`ESACTIVO_FAM` AS `ESACTIVO_FAM`,`fza_articulos_familias`.`ORDEN_FAM` AS `ORDEN_FAM`,`fza_articulos_familias`.`ESDEFAULT_FAM` AS `ESDEFAULT_FAM`,`fza_articulos_familias`.`CODIGO_SUBFAMILIA_FAM` AS `CODIGO_SUBFAMILIA_FAM`,`fza_articulos_familias`.`NOMBRE_FAM_FAM` AS `NOMBRE_FAM_FAM`,`fza_articulos_familias`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`fza_articulos_familias`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_articulos_familias`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_articulos_familias`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_articulos_familias`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_articulos_familias` where `fza_articulos_familias`.`ESACTIVO_FAM` = 'S' order by `fza_articulos_familias`.`ORDEN_FAM`;

-- Vista: vi_articulos_fotos
DROP TABLE IF EXISTS `vi_articulos_fotos`;
DROP VIEW IF EXISTS `vi_articulos_fotos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_fotos` AS select `sku`.`CODIGO_ART_SKU` AS `CODIGO_ART`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,coalesce(`fs`.`NOMBRE_FOT_FOT`,`fa`.`NOMBRE_FOT_FOT`) AS `NOMBRE_FOT`,coalesce(`fs`.`EXTENSION_ORIGEN_FOT`,`fa`.`EXTENSION_ORIGEN_FOT`) AS `EXTENSION_ORIGEN_FOT`,case when `fs`.`NOMBRE_FOT_FOT` is not null then 'SKU' when `fa`.`NOMBRE_FOT_FOT` is not null then 'ARTICULO' else NULL end AS `ORIGEN_FOT` from ((`fza_articulos_skus` `sku` left join `fza_articulos_fotos` `fs` on(`fs`.`CODIGO_ART_FOT` = `sku`.`CODIGO_ART_SKU` and `fs`.`CODIGO_UNIDAD_FOT` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `fza_articulos_fotos` `fa` on(`fa`.`CODIGO_ART_FOT` = `sku`.`CODIGO_ART_SKU` and `fa`.`CODIGO_UNIDAD_FOT` = ''));

-- Vista: vi_articulos_list
DROP TABLE IF EXISTS `vi_articulos_list`;
DROP VIEW IF EXISTS `vi_articulos_list`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_list` AS select `fza_articulos`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,`fza_articulos`.`ESACTIVO_ART` AS `ESACTIVO_ART`,`fza_articulos`.`ORDEN_ART` AS `ORDEN_ART`,`fza_articulos`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`fza_articulos`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`fza_articulos_familias`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`fza_articulos`.`TIPO_IVA_ART` AS `TIPO_IVA_ART`,`fza_articulos`.`ESACTIVO_FIJO_ART` AS `ESACTIVO_FIJO_ART`,`fza_articulos`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`fza_articulos_proveedores`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`fza_proveedores`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`fza_articulos`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_articulos`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_articulos`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_articulos`.`USUARIO_MODIF` AS `USUARIO_MODIF` from (((`fza_articulos` left join `fza_articulos_familias` on(`fza_articulos`.`CODIGO_FAM_ART` = `fza_articulos_familias`.`CODIGO_FAM_FAM`)) left join `fza_articulos_proveedores` on(`fza_articulos_proveedores`.`CODIGO_ART_AP` = `fza_articulos`.`CODIGO_ART_ART` and `fza_articulos_proveedores`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` on(`fza_proveedores`.`CODIGO_PRV_PRV` = `fza_articulos_proveedores`.`CODIGO_PRV_AP`)) where `fza_articulos`.`ESACTIVO_ART` = 'S' order by `fza_articulos`.`ORDEN_ART`;

-- Vista: vi_articulos_pdte_recibir
DROP TABLE IF EXISTS `vi_articulos_pdte_recibir`;
DROP VIEW IF EXISTS `vi_articulos_pdte_recibir`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_pdte_recibir` AS select `fza_articulos_pdte_recibir`.`CODIGO_UNIDAD_PDR` AS `CODIGO_UNIDAD_SKU`,`fza_articulos_pdte_recibir`.`CODIGO_ALM_PDR` AS `CODIGO_ALM_ALM`,`fza_articulos_pdte_recibir`.`CODIGO_ART_PDR` AS `CODIGO_ART_ART`,sum(`fza_articulos_pdte_recibir`.`CANTIDAD_PDR`) AS `CANTIDAD_PTE_RECIBIR`,count(0) AS `NUM_LINEAS_PDR`,min(`fza_articulos_pdte_recibir`.`FECHA_PEDIDO_PDR`) AS `FECHA_PEDIDO_MIN`,min(`fza_articulos_pdte_recibir`.`FECHA_PREVISTA_PDR`) AS `FECHA_PREVISTA_MIN` from `fza_articulos_pdte_recibir` group by `fza_articulos_pdte_recibir`.`CODIGO_UNIDAD_PDR`,`fza_articulos_pdte_recibir`.`CODIGO_ALM_PDR`,`fza_articulos_pdte_recibir`.`CODIGO_ART_PDR`;

-- Vista: vi_articulos_propiedades_efectivas
DROP TABLE IF EXISTS `vi_articulos_propiedades_efectivas`;
DROP VIEW IF EXISTS `vi_articulos_propiedades_efectivas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_propiedades_efectivas` AS select `sku`.`CODIGO_ART_SKU` AS `CODIGO_ART`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`pr`.`CODIGO_PROP_ARTPROP` AS `CODIGO_PROP_ARTPROP`,coalesce(`ps`.`ID_PV_ARTPROP`,`pc`.`ID_PV_ARTPROP`,`pa`.`ID_PV_ARTPROP`) AS `ID_PV_ARTPROP`,coalesce(`ps`.`VALOR_LIBRE_ARTPROP`,`pc`.`VALOR_LIBRE_ARTPROP`,`pa`.`VALOR_LIBRE_ARTPROP`) AS `VALOR_LIBRE_ARTPROP`,`pv`.`PV` AS `VALOR_PV`,case when `ps`.`CODIGO_ART_ART` is not null then 'SKU' when `pc`.`CODIGO_ART_ART` is not null then 'COLOR' when `pa`.`CODIGO_ART_ART` is not null then 'ARTICULO' else NULL end AS `ORIGEN_PROP` from (((((`fza_articulos_skus` `sku` join (select distinct `fza_articulos_propiedades`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,`fza_articulos_propiedades`.`CODIGO_PROP_ARTPROP` AS `CODIGO_PROP_ARTPROP` from `fza_articulos_propiedades`) `pr` on(`pr`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU`)) left join `fza_articulos_propiedades` `ps` on(`ps`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `ps`.`CODIGO_PROP_ARTPROP` = `pr`.`CODIGO_PROP_ARTPROP` and `ps`.`CODIGO_UNIDAD_ARTPROP` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `fza_articulos_propiedades` `pc` on(`pc`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `pc`.`CODIGO_PROP_ARTPROP` = `pr`.`CODIGO_PROP_ARTPROP` and `pc`.`CODIGO_UNIDAD_ARTPROP` = case when char_length(`sku`.`CODIGO_UNIDAD_SKU`) - char_length(replace(`sku`.`CODIGO_UNIDAD_SKU`,'/','')) >= 2 then substring_index(`sku`.`CODIGO_UNIDAD_SKU`,'/',2) else NULL end)) left join `fza_articulos_propiedades` `pa` on(`pa`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `pa`.`CODIGO_PROP_ARTPROP` = `pr`.`CODIGO_PROP_ARTPROP` and `pa`.`CODIGO_UNIDAD_ARTPROP` = '')) left join `fza_propiedades_valores` `pv` on(`pv`.`ID_PV_ARTPROP` = coalesce(`ps`.`ID_PV_ARTPROP`,`pc`.`ID_PV_ARTPROP`,`pa`.`ID_PV_ARTPROP`))) where `sku`.`ESACTIVO_SKU` = 'S';

-- Vista: vi_articulos_propiedades_slots
DROP TABLE IF EXISTS `vi_articulos_propiedades_slots`;
DROP VIEW IF EXISTS `vi_articulos_propiedades_slots`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_propiedades_slots` AS select `a`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,`fa`.`CODIGO_FAM_FAM` AS `CODIGO_FAM_FAM`,`p`.`CODIGO_PROP_ARTPROP` AS `CODIGO_PROP_ARTPROP`,`p`.`NOMBRE_PROP_PROP` AS `NOMBRE_PROP_PROP`,`p`.`TIPO_VALOR_PROP` AS `TIPO_VALOR_PROP`,`fa`.`ESREQUERIDO_FA` AS `ESREQUERIDO_FA`,`fa`.`ORDEN_MOSTRAR_FA` AS `ORDEN_MOSTRAR_FA`,`ap`.`ID_PV_ARTPROP` AS `ID_PV_ARTPROP`,`ap`.`VALOR_LIBRE_ARTPROP` AS `VALOR_LIBRE_ARTPROP`,coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) AS `VALOR_FINAL_MOSTRAR` from ((((`fza_articulos` `a` join `fza_familias_atributos` `fa` on(`a`.`CODIGO_FAM_ART` = `fa`.`CODIGO_FAM_FAM`)) join `fza_propiedades` `p` on(`fa`.`CODIGO_PROP_ARTPROP` = `p`.`CODIGO_PROP_ARTPROP`)) left join `fza_articulos_propiedades` `ap` on(`a`.`CODIGO_ART_ART` = `ap`.`CODIGO_ART_ART` and `p`.`CODIGO_PROP_ARTPROP` = `ap`.`CODIGO_PROP_ARTPROP`)) left join `fza_propiedades_valores` `pv` on(`ap`.`ID_PV_ARTPROP` = `pv`.`ID_PV_ARTPROP`)) order by `a`.`CODIGO_ART_ART`,`fa`.`ORDEN_MOSTRAR_FA`;

-- Vista: vi_articulos_proveedores
DROP TABLE IF EXISTS `vi_articulos_proveedores`;
DROP VIEW IF EXISTS `vi_articulos_proveedores`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_proveedores` AS select `ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`ap`.`CODIGO_ART_AP` AS `CODIGO_ART_ART`,`p`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`ap`.`REF_PROVEEDOR_AP` AS `REF_PROVEEDOR`,`ap`.`PRECIO_ULT_COMPRA_AP` AS `PRECIO_ULT_COMPRA`,`ap`.`FECHA_VALIDEZ_AP` AS `FECHA_VALIDEZ`,`ap`.`ESPROVEEDORPRINCIPAL_AP` AS `ESPROVEEDORPRINCIPAL`,`ap`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`ap`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`ap`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`ap`.`USUARIO_MODIF` AS `USUARIO_MODIF` from (`fza_articulos_proveedores` `ap` left join `fza_proveedores` `p` on(`ap`.`CODIGO_PRV_AP` = `p`.`CODIGO_PRV_PRV`));

-- Vista: vi_articulos_skus
DROP TABLE IF EXISTS `vi_articulos_skus`;
DROP VIEW IF EXISTS `vi_articulos_skus`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_skus` AS select `fza_articulos_skus`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`fza_articulos_skus`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,`fza_articulos_skus`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,`fza_articulos_skus`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,`fza_articulos_skus`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_articulos_skus`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_articulos_skus`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_articulos_skus`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_articulos_skus`;

-- Vista: vi_articulos_skus_con_coste
DROP TABLE IF EXISTS `vi_articulos_skus_con_coste`;
DROP VIEW IF EXISTS `vi_articulos_skus_con_coste`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_skus_con_coste` AS select `sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`sku`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,`sku`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,`sku`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,`skuc`.`PRECIO_ULT_COMPRA_SKUC` AS `PRECIO_ULT_COMPRA_SKUC`,`skuc`.`FECHA_ULT_COMPRA_SKUC` AS `FECHA_ULT_COMPRA_SKUC`,`sku`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`sku`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`sku`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`sku`.`USUARIO_MODIF` AS `USUARIO_MODIF` from (`fza_articulos_skus` `sku` left join `fza_articulos_skus_costes` `skuc` on(`skuc`.`CODIGO_UNIDAD_SKU_SKUC` = `sku`.`CODIGO_UNIDAD_SKU`));

-- Vista: vi_articulos_skus_etiquetas
DROP TABLE IF EXISTS `vi_articulos_skus_etiquetas`;
DROP VIEW IF EXISTS `vi_articulos_skus_etiquetas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_skus_etiquetas` AS with sku_atrib as (select `sa`.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD_SKU`,max(case when `av`.`ID_VA_AV` = 'CO' then `av`.`AV` end) AS `ATR_CO`,max(case when `av`.`ID_VA_AV` = 'TAL' then `av`.`AV` end) AS `ATR_TAL`,group_concat(concat(coalesce(`va`.`NOMBRE_VA`,`av`.`ID_VA_AV`),': ',`av`.`AV`) order by coalesce(`va`.`ORDEN_VA`,99) ASC,`av`.`ID_VA_AV` ASC separator ' / ') AS `ATRIBUTOS_TXT`,group_concat(`av`.`AV` order by coalesce(`va`.`ORDEN_VA`,99) ASC,`av`.`ID_VA_AV` ASC separator ' / ') AS `DESCRIPCION_SKU` from ((`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA`)) left join `fza_variaciones_atributos` `va` on(`va`.`ID_ATB_VA` = `av`.`ID_VA_AV`)) group by `sa`.`CODIGO_UNIDAD_SKU_SA`), art_prop as (select `ap`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'MARCA' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_MARCA`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'MATERIAL' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_MATERIAL`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'GENERO' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_GENERO`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'ESTILO' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_ESTILO`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'ORIGEN' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_ORIGEN`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'COMPOSICION' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_COMPOSICION`,group_concat(concat(coalesce(`p`.`NOMBRE_PROP_PROP`,`ap`.`CODIGO_PROP_ARTPROP`),': ',coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`,'')) order by `ap`.`CODIGO_PROP_ARTPROP` ASC separator ' | ') AS `PROPIEDADES_TXT` from ((`fza_articulos_propiedades` `ap` left join `fza_propiedades` `p` on(`p`.`CODIGO_PROP_ARTPROP` = `ap`.`CODIGO_PROP_ARTPROP`)) left join `fza_propiedades_valores` `pv` on(`pv`.`ID_PV_ARTPROP` = `ap`.`ID_PV_ARTPROP`)) group by `ap`.`CODIGO_ART_ART`), sku_temp as (select `sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,coalesce(`tpv`.`PV`,`tps`.`VALOR_LIBRE_ARTPROP`,`tpc`.`VALOR_LIBRE_ARTPROP`,`tpa`.`VALOR_LIBRE_ARTPROP`) AS `PROP_TEMPORADA`,`tpv`.`DESCRIPCION_PV` AS `DESCRIPCION_TEMPORADA`,`tpv`.`DESCRIPCION_PV` AS `COD_TEMPORADA` from ((((`fza_articulos_skus` `sku` left join `fza_articulos_propiedades` `tps` on(`tps`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `tps`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA' and `tps`.`CODIGO_UNIDAD_ARTPROP` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `fza_articulos_propiedades` `tpc` on(`tpc`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `tpc`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA' and `tpc`.`CODIGO_UNIDAD_ARTPROP` = case when char_length(`sku`.`CODIGO_UNIDAD_SKU`) - char_length(replace(`sku`.`CODIGO_UNIDAD_SKU`,'/','')) >= 2 then substring_index(`sku`.`CODIGO_UNIDAD_SKU`,'/',2) else NULL end)) left join `fza_articulos_propiedades` `tpa` on(`tpa`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `tpa`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA' and `tpa`.`CODIGO_UNIDAD_ARTPROP` = '')) left join `fza_propiedades_valores` `tpv` on(`tpv`.`ID_PV_ARTPROP` = coalesce(`tps`.`ID_PV_ARTPROP`,`tpc`.`ID_PV_ARTPROP`,`tpa`.`ID_PV_ARTPROP`)))), cb_prin as (select `fza_codigos_barras`.`CODIGO_UNIDAD_CB` AS `CODIGO_UNIDAD_CB`,max(`fza_codigos_barras`.`CODIGO_BARRAS_CB`) AS `CODIGO_BARRAS_CB` from `fza_codigos_barras` where `fza_codigos_barras`.`ESPRINCIPAL_CB` = 'S' group by `fza_codigos_barras`.`CODIGO_UNIDAD_CB`)select `sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`sku`.`CODIGO_ART_SKU` AS `CODIGO_ART_ART`,`sku`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,`sku`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,`art`.`ESACTIVO_ART` AS `ESACTIVO_ART`,`art`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`art`.`TIPO_ART` AS `TIPO_ART`,`art`.`TIPO_IVA_ART` AS `TIPO_IVA_ART`,`art`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`fam`.`NOMBRE_FAM_FAM` AS `NOMBRE_FAM_FAM`,`fam`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`sa`.`ATR_CO` AS `ATR_CO`,`sa`.`ATR_TAL` AS `ATR_TAL`,`sa`.`ATRIBUTOS_TXT` AS `ATRIBUTOS_TXT`,`sa`.`DESCRIPCION_SKU` AS `DESCRIPCION_SKU`,`apr`.`PROP_MARCA` AS `PROP_MARCA`,`apr`.`PROP_MATERIAL` AS `PROP_MATERIAL`,`st`.`PROP_TEMPORADA` AS `PROP_TEMPORADA`,`st`.`DESCRIPCION_TEMPORADA` AS `DESCRIPCION_TEMPORADA`,`st`.`COD_TEMPORADA` AS `COD_TEMPORADA`,`apr`.`PROP_GENERO` AS `PROP_GENERO`,`apr`.`PROP_ESTILO` AS `PROP_ESTILO`,`apr`.`PROP_ORIGEN` AS `PROP_ORIGEN`,`apr`.`PROP_COMPOSICION` AS `PROP_COMPOSICION`,`apr`.`PROPIEDADES_TXT` AS `PROPIEDADES_TXT`,`ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`prv`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`prv`.`NOMBRE_PRV` AS `NOMBRE_PRV`,`ap`.`REF_PROVEEDOR_AP` AS `REF_PROVEEDOR`,`cb`.`CODIGO_BARRAS_CB` AS `CODIGO_BARRAS_CB` from ((((((((`fza_articulos_skus` `sku` join `fza_articulos` `art` on(`art`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU`)) left join `fza_articulos_familias` `fam` on(`fam`.`CODIGO_FAM_FAM` = `art`.`CODIGO_FAM_ART`)) left join `sku_atrib` `sa` on(`sa`.`CODIGO_UNIDAD_SKU` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `art_prop` `apr` on(`apr`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU`)) left join `sku_temp` `st` on(`st`.`CODIGO_UNIDAD_SKU` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `fza_articulos_proveedores` `ap` on(`ap`.`CODIGO_ART_AP` = `sku`.`CODIGO_ART_SKU` and `ap`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` `prv` on(`prv`.`CODIGO_PRV_PRV` = `ap`.`CODIGO_PRV_AP`)) left join `cb_prin` `cb` on(`cb`.`CODIGO_UNIDAD_CB` = `sku`.`CODIGO_UNIDAD_SKU`));

-- Vista: vi_articulos_skus_extendida
DROP TABLE IF EXISTS `vi_articulos_skus_extendida`;
DROP VIEW IF EXISTS `vi_articulos_skus_extendida`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_skus_extendida` AS select `sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`sku`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,`sku`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,`sku`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,`cb`.`ID_CB` AS `ID_CB`,`cb`.`CODIGO_BARRAS_CB` AS `CODIGO_BARRAS_CB`,`cb`.`TIPO_CODIGO_CB` AS `TIPO_CODIGO_CB`,`cb`.`ESPRINCIPAL_CB` AS `ESPRINCIPAL_CB`,coalesce(`stk`.`STOCK_TOTAL`,0) AS `STOCK_TOTAL`,`sku`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`sku`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`sku`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`sku`.`USUARIO_MODIF` AS `USUARIO_MODIF` from ((`fza_articulos_skus` `sku` join `fza_codigos_barras` `cb` on(`cb`.`CODIGO_UNIDAD_CB` = `sku`.`CODIGO_UNIDAD_SKU`)) left join (select `fza_articulos_stockactual`.`CODIGO_UNIDAD_STK` AS `CODIGO_UNIDAD_STK`,sum(`fza_articulos_stockactual`.`CANTIDAD_STK`) AS `STOCK_TOTAL` from `fza_articulos_stockactual` group by `fza_articulos_stockactual`.`CODIGO_UNIDAD_STK`) `stk` on(`sku`.`CODIGO_UNIDAD_SKU` = `stk`.`CODIGO_UNIDAD_STK`));

-- Vista: vi_articulos_tarifas
DROP TABLE IF EXISTS `vi_articulos_tarifas`;
DROP VIEW IF EXISTS `vi_articulos_tarifas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_tarifas` AS select `at`.`CODIGO_ART_ARTTAR` AS `CODIGO_ART_ARTTAR`,coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') AS `CODIGO_UNIDAD_ARTTAR`,`at`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR`,`t`.`NOMBRE_TAR_TAR` AS `NOMBRE_TAR_TAR`,`at`.`CODIGO_UNICO_ARTTAR` AS `CODIGO_UNICO_ARTTAR`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then `at`.`CODIGO_UNICO_ARTTAR` end AS `CODIGO_UNICO_TARIFA_SKU`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') = '' then `at`.`CODIGO_UNICO_ARTTAR` end AS `CODIGO_UNICO_TARIFA_PADRE`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then 'ESPECIFICO_SKU' else 'PADRE' end AS `ORIGEN_PRECIO`,`at`.`PRECIO_SALIDA_ARTTAR` AS `PRECIO_SALIDA_ARTTAR`,`at`.`PRECIO_FINAL_ARTTAR` AS `PRECIO_FINAL_ARTTAR`,`at`.`PRECIO_DTO_ARTTAR` AS `PRECIO_DTO_ARTTAR`,`at`.`PORCENTAJE_DTO_ARTTAR` AS `PORCENTAJE_DTO_ARTTAR`,`at`.`PORCENTAJE_MARGEN_ARTTAR` AS `PORCENTAJE_MARGEN_ARTTAR`,`at`.`VALOR_MULTIPLO_AJUSTE_ARTTAR` AS `VALOR_MULTIPLO_AJUSTE_ARTTAR`,`at`.`VALOR_MENOS_AJUSTE_ARTTAR` AS `VALOR_MENOS_AJUSTE_ARTTAR`,coalesce(`at`.`PORCENTAJE_MARGEN_ARTTAR`,`t`.`PORCENTAJE_MARGEN_TAR`) AS `PORCENTAJE_MARGEN_EFECTIVO`,coalesce(`at`.`VALOR_MULTIPLO_AJUSTE_ARTTAR`,`t`.`VALOR_MULTIPLO_AJUSTE_TAR`) AS `VALOR_MULTIPLO_AJUSTE_EFECTIVO`,coalesce(`at`.`VALOR_MENOS_AJUSTE_ARTTAR`,`t`.`VALOR_MENOS_AJUSTE_TAR`) AS `VALOR_MENOS_AJUSTE_EFECTIVO`,`at`.`FECHA_DESDE_ARTTAR` AS `FECHA_DESDE_ARTTAR`,`at`.`FECHA_HASTA_ARTTAR` AS `FECHA_HASTA_ARTTAR`,`t`.`ESACTIVO_ARTTAR` AS `ESACTIVO_ARTTAR`,`t`.`ESIMP_INCL_TAR` AS `ESIMP_INCL_TAR`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`a`.`ESVARIACION_ART` AS `ESVARIACION_ART`,`iv`.`CODIGO_ABREVIATURA_IVA_IVATIP` AS `TIPO_IVA_ARTICULO`,case when `tiene_sku`.`CODIGO_ART_SKU` is not null then 'S' else 'N' end AS `TIENE_SKU`,`sku`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,(select group_concat(`av`.`AV` order by `av`.`ORDEN_AV` ASC separator ' / ') from (`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA`)) where `sa`.`CODIGO_UNIDAD_SKU_SA` = `at`.`CODIGO_UNIDAD_ARTTAR`) AS `DESCRIPCION_SKU`,`ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`p`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then `skuc`.`PRECIO_ULT_COMPRA_SKUC` else `ap`.`PRECIO_ULT_COMPRA_AP` end AS `PRECIO_ULT_COMPRA`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then `skuc`.`FECHA_ULT_COMPRA_SKUC` else `ap`.`FECHA_VALIDEZ_AP` end AS `FECHA_VALIDEZ`,`a`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`af`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,coalesce(`num_atr`.`NUM_ATRIBUTOS_REQ`,0) AS `NUM_ATRIBUTOS_REQ`,`at`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`at`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`at`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`at`.`USUARIO_MODIF` AS `USUARIO_MODIF` from ((((((((((`fza_articulos_tarifas` `at` join `fza_articulos` `a` on(`a`.`CODIGO_ART_ART` = `at`.`CODIGO_ART_ARTTAR`)) join `fza_tarifas` `t` on(`t`.`CODIGO_TAR_ARTTAR` = `at`.`CODIGO_TAR_ARTTAR`)) left join `fza_articulos_skus` `sku` on(`sku`.`CODIGO_UNIDAD_SKU` = `at`.`CODIGO_UNIDAD_ARTTAR` and coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '')) left join `fza_articulos_skus_costes` `skuc` on(`skuc`.`CODIGO_UNIDAD_SKU_SKUC` = `at`.`CODIGO_UNIDAD_ARTTAR` and coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '')) left join `fza_articulos_proveedores` `ap` on(`ap`.`CODIGO_ART_AP` = `a`.`CODIGO_ART_ART` and `ap`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` `p` on(`p`.`CODIGO_PRV_PRV` = `ap`.`CODIGO_PRV_AP`)) left join `fza_articulos_familias` `af` on(`af`.`CODIGO_FAM_FAM` = `a`.`CODIGO_FAM_ART`)) left join `fza_ivas_tipos` `iv` on(`iv`.`CODIGO_ABREVIATURA_IVA_IVATIP` = `a`.`TIPO_IVA_ART`)) left join (select distinct `fza_articulos_skus`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU` from `fza_articulos_skus` where `fza_articulos_skus`.`ESACTIVO_SKU` = 'S') `tiene_sku` on(`tiene_sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) left join (select `sk`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,count(distinct `va`.`ID_ATB_VA`) AS `NUM_ATRIBUTOS_REQ` from (`fza_articulos_skus` `sk` join `fza_variaciones_atributos` `va` on(`va`.`ID_VAR_VA` = `sk`.`CODIGO_VAR_SKU`)) group by `sk`.`CODIGO_ART_SKU`) `num_atr` on(`num_atr`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) where `at`.`ESACTIVO_ARTTAR` = 'S' and `t`.`ESACTIVO_ARTTAR` = 'S' and (`at`.`FECHA_HASTA_ARTTAR` is null or `at`.`FECHA_HASTA_ARTTAR` >= curdate()) order by `t`.`ORDEN_TAR`,`a`.`ORDEN_ART`,`at`.`CODIGO_UNIDAD_ARTTAR`;

