DROP VIEW IF EXISTS `vi_articulos_tarifas_mto`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_articulos_tarifas_mto` AS select `at`.`CODIGO_ART_ARTTAR` AS `CODIGO_ART_ARTTAR`,coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') AS `CODIGO_UNIDAD_ARTTAR`,`at`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR`,`t`.`NOMBRE_TAR_TAR` AS `NOMBRE_TAR_TAR`,`at`.`CODIGO_UNICO_ARTTAR` AS `CODIGO_UNICO_ARTTAR`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then `at`.`CODIGO_UNICO_ARTTAR` end AS `CODIGO_UNICO_TARIFA_SKU`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') = '' then `at`.`CODIGO_UNICO_ARTTAR` end AS `CODIGO_UNICO_TARIFA_PADRE`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then 'ESPECIFICO_SKU' else 'PADRE' end AS `ORIGEN_PRECIO`,`at`.`PRECIO_SALIDA_ARTTAR` AS `PRECIO_SALIDA_ARTTAR`,`at`.`PRECIO_FINAL_ARTTAR` AS `PRECIO_FINAL_ARTTAR`,`at`.`PRECIO_DTO_ARTTAR` AS `PRECIO_DTO_ARTTAR`,`at`.`PORCENTAJE_DTO_ARTTAR` AS `PORCENTAJE_DTO_ARTTAR`,`at`.`PORCENTAJE_MARGEN_ARTTAR` AS `PORCENTAJE_MARGEN_ARTTAR`,`at`.`VALOR_MULTIPLO_AJUSTE_ARTTAR` AS `VALOR_MULTIPLO_AJUSTE_ARTTAR`,`at`.`VALOR_MENOS_AJUSTE_ARTTAR` AS `VALOR_MENOS_AJUSTE_ARTTAR`,coalesce(`at`.`PORCENTAJE_MARGEN_ARTTAR`,`t`.`PORCENTAJE_MARGEN_TAR`) AS `PORCENTAJE_MARGEN_EFECTIVO`,coalesce(`at`.`VALOR_MULTIPLO_AJUSTE_ARTTAR`,`t`.`VALOR_MULTIPLO_AJUSTE_TAR`) AS `VALOR_MULTIPLO_AJUSTE_EFECTIVO`,coalesce(`at`.`VALOR_MENOS_AJUSTE_ARTTAR`,`t`.`VALOR_MENOS_AJUSTE_TAR`) AS `VALOR_MENOS_AJUSTE_EFECTIVO`,`at`.`FECHA_DESDE_ARTTAR` AS `FECHA_DESDE_ARTTAR`,`at`.`FECHA_HASTA_ARTTAR` AS `FECHA_HASTA_ARTTAR`,`t`.`ESACTIVO_ARTTAR` AS `ESACTIVO_ARTTAR`,`t`.`ESIMP_INCL_TAR` AS `ESIMP_INCL_TAR`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`a`.`ESVARIACION_ART` AS `ESVARIACION_ART`,`iv`.`CODIGO_ABREVIATURA_IVA_IVATIP` AS `TIPO_IVA_ARTICULO`,case when `tiene_sku`.`CODIGO_ART_SKU` is not null then 'S' else 'N' end AS `TIENE_SKU`,`sku`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,(select group_concat(`av`.`AV` order by `av`.`ORDEN_AV` ASC separator ' / ') from (`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA`)) where `sa`.`CODIGO_UNIDAD_SKU_SA` = `at`.`CODIGO_UNIDAD_ARTTAR`) AS `DESCRIPCION_SKU`,`ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`p`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then `skuc`.`PRECIO_ULT_COMPRA_SKUC` else `ap`.`PRECIO_ULT_COMPRA_AP` end AS `PRECIO_ULT_COMPRA`,case when coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '' then `skuc`.`FECHA_ULT_COMPRA_SKUC` else `ap`.`FECHA_VALIDEZ_AP` end AS `FECHA_VALIDEZ`,`a`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`af`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,coalesce(`num_atr`.`NUM_ATRIBUTOS_REQ`,0) AS `NUM_ATRIBUTOS_REQ`,`at`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`at`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`at`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`at`.`USUARIO_MODIF` AS `USUARIO_MODIF` from ((((((((((`fza_articulos_tarifas` `at` join `fza_articulos` `a` on(`a`.`CODIGO_ART_ART` = `at`.`CODIGO_ART_ARTTAR`)) join `fza_tarifas` `t` on(`t`.`CODIGO_TAR_ARTTAR` = `at`.`CODIGO_TAR_ARTTAR`)) left join `fza_articulos_skus` `sku` on(`sku`.`CODIGO_UNIDAD_SKU` = `at`.`CODIGO_UNIDAD_ARTTAR` and coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '')) left join `fza_articulos_skus_costes` `skuc` on(`skuc`.`CODIGO_UNIDAD_SKU_SKUC` = `at`.`CODIGO_UNIDAD_ARTTAR` and coalesce(`at`.`CODIGO_UNIDAD_ARTTAR`,'') <> '')) left join `fza_articulos_proveedores` `ap` on(`ap`.`CODIGO_ART_AP` = `a`.`CODIGO_ART_ART` and `ap`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` `p` on(`p`.`CODIGO_PRV_PRV` = `ap`.`CODIGO_PRV_AP`)) left join `fza_articulos_familias` `af` on(`af`.`CODIGO_FAM_FAM` = `a`.`CODIGO_FAM_ART`)) left join `fza_ivas_tipos` `iv` on(`iv`.`CODIGO_ABREVIATURA_IVA_IVATIP` = `a`.`TIPO_IVA_ART`)) left join (select distinct `fza_articulos_skus`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU` from `fza_articulos_skus` where `fza_articulos_skus`.`ESACTIVO_SKU` = 'S') `tiene_sku` on(`tiene_sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) left join (select `sk`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,count(distinct `va`.`ID_ATB_VA`) AS `NUM_ATRIBUTOS_REQ` from (`fza_articulos_skus` `sk` join `fza_variaciones_atributos` `va` on(`va`.`ID_VAR_VA` = `sk`.`CODIGO_VAR_SKU`)) group by `sk`.`CODIGO_ART_SKU`) `num_atr` on(`num_atr`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) where `t`.`ESACTIVO_ARTTAR` = 'S' order by `t`.`ORDEN_TAR`,`a`.`ORDEN_ART`,`at`.`CODIGO_UNIDAD_ARTTAR`;

-- Vista: vi_atributos_nombres
DROP TABLE IF EXISTS `vi_atributos_nombres`;
DROP VIEW IF EXISTS `vi_atributos_nombres`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_atributos_nombres` AS select `ask`.`CODIGO_ART_SKU` AS `CODIGO_ART_PADRE_ARTVIN`,`vat`.`ID_ATB_VA` AS `ID_ATRIBUTO`,`vat`.`NOMBRE_VA` AS `NOMBRE_ATRIBUTO`,`vat`.`ORDEN_VA` AS `ORDEN_VISUAL_ATRIBUTO` from (`fza_articulos_skus` `ask` join `fza_variaciones_atributos` `vat` on(`vat`.`ID_VAR_VA` = `ask`.`CODIGO_VAR_SKU`)) order by `ask`.`CODIGO_ART_SKU`,`vat`.`ORDEN_VA`;

-- Vista: vi_atributos_sku_basico
DROP TABLE IF EXISTS `vi_atributos_sku_basico`;
DROP VIEW IF EXISTS `vi_atributos_sku_basico`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_atributos_sku_basico` AS select `sku`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`sku`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,`val`.`ID_AV` AS `ID_AV`,`val`.`ID_VA_AV` AS `ID_VA_AV`,`va`.`NOMBRE_VA` AS `NOMBRE_ATRIBUTO`,`va`.`ORDEN_VA` AS `ORDEN_ATRIBUTO`,`val`.`AV` AS `VALOR_AV`,`val`.`DESCRIPCION_AV` AS `DESCRIPCION_AV`,`aca`.`ID_AC_ACA` AS `ID_AC`,`aab`.`ID_ATB_AAB` AS `ID_ATB_OVERRIDE`,`acd`.`ID_ATB_ACD` AS `ID_ATB_CONJUNTO`,`val`.`ID_ATB_AV` AS `ID_ATB_GLOBAL`,case when `aab`.`CODIGO_ART_AAB` is not null then `aab`.`ID_ATB_AAB` when `acd`.`ID_ATB_ACD` is not null then `acd`.`ID_ATB_ACD` else `val`.`ID_ATB_AV` end AS `ID_ATB_AV`,case when `aab`.`CODIGO_ART_AAB` is not null then 'A' when `acd`.`ID_ATB_ACD` is not null then 'C' when `val`.`ID_ATB_AV` is not null then 'G' else NULL end AS `FUENTE_ATB`,`atb`.`CODIGO_ATB` AS `CODIGO_ATB`,`atb`.`NOMBRE_ATB` AS `NOMBRE_ATB`,`atb`.`DESCRIPCION_ATB` AS `DESCRIPCION_ATB`,`atb`.`HEX_ATB` AS `HEX_ATB`,`atb`.`VALOR_NUM_ATB` AS `VALOR_NUM_ATB`,`atb`.`UNIDAD_ATB` AS `UNIDAD_ATB`,case when `atb`.`VALOR_NUM_ATB` is not null then concat(trim(trailing '0' from trim(trailing '.' from cast(`atb`.`VALOR_NUM_ATB` as char charset utf8mb4) collate utf8mb4_spanish_ci)),coalesce(concat(' ',`atb`.`UNIDAD_ATB`),'')) when `atb`.`HEX_ATB` is not null then concat(`atb`.`NOMBRE_ATB`,' ',`atb`.`HEX_ATB`) else `atb`.`NOMBRE_ATB` end AS `ETIQUETA_BASICO`,`aab`.`DESCRIPCION_AAB` AS `DESCRIPCION_AAB` from (((((((`fza_articulos_skus` `sku` join `fza_atributos_sku` `sa` on(`sa`.`CODIGO_UNIDAD_SKU_SA` = `sku`.`CODIGO_UNIDAD_SKU`)) join `fza_atributos_valores` `val` on(`val`.`ID_AV` = `sa`.`ID_AV_SA`)) left join `fza_variaciones_atributos` `va` on(`va`.`ID_VAR_VA` = `sku`.`CODIGO_VAR_SKU` and `va`.`ID_ATB_VA` = `val`.`ID_VA_AV`)) left join `fza_articulos_atributos_basicos` `aab` on(`aab`.`CODIGO_ART_AAB` = `sku`.`CODIGO_ART_SKU` and `aab`.`ID_AV_AAB` = `val`.`ID_AV`)) left join `fza_articulos_conjuntos_asign` `aca` on(`aca`.`CODIGO_ART_ACA` = `sku`.`CODIGO_ART_SKU` and `aca`.`ID_VA_ACA` = `val`.`ID_VA_AV`)) left join `fza_atributos_conjuntos_det` `acd` on(`acd`.`ID_AC_ACD` = `aca`.`ID_AC_ACA` and `acd`.`ID_AV_ACD` = `val`.`ID_AV`)) left join `fza_atributos_basicos` `atb` on(`atb`.`ID_ATB` = case when `aab`.`CODIGO_ART_AAB` is not null then `aab`.`ID_ATB_AAB` when `acd`.`ID_ATB_ACD` is not null then `acd`.`ID_ATB_ACD` else `val`.`ID_ATB_AV` end)) union all select `sku`.`CODIGO_ART_SKU` AS `CODIGO_ART_SKU`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`sku`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,NULL AS `ID_AV`,`va`.`ID_ATB_VA` AS `ID_VA_AV`,`va`.`NOMBRE_VA` AS `NOMBRE_ATRIBUTO`,`va`.`ORDEN_VA` AS `ORDEN_ATRIBUTO`,substring_index(substring_index(substr(`sku`.`CODIGO_UNIDAD_SKU`,char_length(`sku`.`CODIGO_ART_SKU`) + 2),'/',`va`.`ORDEN_VA`),'/',-1) AS `VALOR_AV`,NULL AS `DESCRIPCION_AV`,NULL AS `ID_AC`,NULL AS `ID_ATB_OVERRIDE`,NULL AS `ID_ATB_CONJUNTO`,NULL AS `ID_ATB_GLOBAL`,NULL AS `ID_ATB_AV`,NULL AS `FUENTE_ATB`,NULL AS `CODIGO_ATB`,NULL AS `NOMBRE_ATB`,NULL AS `DESCRIPCION_ATB`,NULL AS `HEX_ATB`,NULL AS `VALOR_NUM_ATB`,NULL AS `UNIDAD_ATB`,NULL AS `ETIQUETA_BASICO`,NULL AS `DESCRIPCION_AAB` from (`fza_articulos_skus` `sku` join `fza_variaciones_atributos` `va` on(`va`.`ID_VAR_VA` = `sku`.`CODIGO_VAR_SKU`)) where `sku`.`CODIGO_UNIDAD_SKU` like concat(`sku`.`CODIGO_ART_SKU`,'/%') and !exists(select 1 from (`fza_atributos_sku` `sa` join `fza_atributos_valores` `v` on(`v`.`ID_AV` = `sa`.`ID_AV_SA`)) where `sa`.`CODIGO_UNIDAD_SKU_SA` = `sku`.`CODIGO_UNIDAD_SKU` and `v`.`ID_VA_AV` = `va`.`ID_ATB_VA` limit 1);

-- Vista: vi_caja_busqueda_unificada
DROP TABLE IF EXISTS `vi_caja_busqueda_unificada`;
DROP VIEW IF EXISTS `vi_caja_busqueda_unificada`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_caja_busqueda_unificada` AS select `a`.`CODIGO_ART_ART` AS `INPUT_BUSQUEDA`,_utf8mb4'CODIGO' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,cast(NULL as char charset utf8mb4) collate utf8mb4_spanish_ci AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART` from `fza_articulos` `a` where `a`.`ESACTIVO_ART` = 'S' union all select `sku`.`CODIGO_UNIDAD_SKU` AS `INPUT_BUSQUEDA`,_utf8mb4'SKU' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART` from (`fza_articulos_skus` `sku` join `fza_articulos` `a` on(`sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) where `sku`.`ESACTIVO_SKU` = 'S' union all select `cb`.`CODIGO_BARRAS_CB` AS `INPUT_BUSQUEDA`,_utf8mb4'EAN' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART` from ((`fza_codigos_barras` `cb` join `fza_articulos_skus` `sku` on(`cb`.`CODIGO_UNIDAD_CB` = `sku`.`CODIGO_UNIDAD_SKU`)) join `fza_articulos` `a` on(`sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) union all select `ap`.`REF_PROVEEDOR_AP` AS `INPUT_BUSQUEDA`,_utf8mb4'MODELO_PROV' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,cast(NULL as char charset utf8mb4) collate utf8mb4_spanish_ci AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART` from (`fza_articulos_proveedores` `ap` join `fza_articulos` `a` on(`ap`.`CODIGO_ART_AP` = `a`.`CODIGO_ART_ART`)) where `a`.`ESACTIVO_ART` = 'S' and `ap`.`REF_PROVEEDOR_AP` is not null and `ap`.`REF_PROVEEDOR_AP` <> '';

-- Vista: vi_caja_pagos
DROP TABLE IF EXISTS `vi_caja_pagos`;
DROP VIEW IF EXISTS `vi_caja_pagos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_caja_pagos` AS select `p`.`CODIGO_EMP_PAGO` AS `CODIGO_EMP_PAGO`,`p`.`CODIGO_ALM_PAGO` AS `CODIGO_ALM_PAGO`,`p`.`CODIGO_CAJA_PAGO` AS `CODIGO_CAJA_PAGO`,`p`.`SERIE_OPERACION_PAGO` AS `SERIE_OPERACION_PAGO`,`p`.`NUMERO_OPERACION_PAGO` AS `NUMERO_OPERACION_PAGO`,`p`.`NUMERO_LINEA_PAGO` AS `NUMERO_LINEA_PAGO`,`p`.`CODIGO_FP_CFP` AS `CODIGO_FP_CFP`,`p`.`CODIGO_DIVISA_PAGO` AS `CODIGO_DIVISA_PAGO`,`p`.`RED_BLOCKCHAIN_PAGO` AS `RED_BLOCKCHAIN_PAGO`,`p`.`FACTOR_CAMBIO_PAGO` AS `FACTOR_CAMBIO_PAGO`,`p`.`IMPORTE_DIVISA_PAGO` AS `IMPORTE_DIVISA_PAGO`,`p`.`IMPORTE_ENTREGADO_PAGO` AS `IMPORTE_ENTREGADO_PAGO`,`p`.`IMPORTE_CAMBIO_PAGO` AS `IMPORTE_CAMBIO_PAGO`,`p`.`REFERENCIA_FACPAG` AS `REFERENCIA_FACPAG`,`p`.`OBSERVACIONES_PAGO` AS `OBSERVACIONES_PAGO`,`p`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`p`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`p`.`USUARIO_ALTA` AS `USUARIO_ALTA`,coalesce(`o`.`FECHA_OP`,`p`.`INSTANTE_ALTA`) AS `FECHA_PAGO`,`o`.`NUM_FAC` AS `NUMERO_FAC_PAGO`,`o`.`SERIE_FAC` AS `SERIE_FAC_PAGO` from (`fza_caja_pagos` `p` left join (select `fza_caja_operaciones`.`CODIGO_EMP_OPCAJA` AS `CODIGO_EMP_OPCAJA`,`fza_caja_operaciones`.`CODIGO_ALM_OPCAJA` AS `CODIGO_ALM_OPCAJA`,`fza_caja_operaciones`.`CODIGO_CAJA_OPCAJA` AS `CODIGO_CAJA_OPCAJA`,`fza_caja_operaciones`.`NUMERO_OPERACION_OPCAJA` AS `NUMERO_OPERACION_OPCAJA`,min(`fza_caja_operaciones`.`FECHA_OPERACION_OPCAJA`) AS `FECHA_OP`,max(`fza_caja_operaciones`.`NUMERO_FAC_OPCAJA`) AS `NUM_FAC`,max(`fza_caja_operaciones`.`SERIE_FAC_OPCAJA`) AS `SERIE_FAC` from `fza_caja_operaciones` group by `fza_caja_operaciones`.`CODIGO_EMP_OPCAJA`,`fza_caja_operaciones`.`CODIGO_ALM_OPCAJA`,`fza_caja_operaciones`.`CODIGO_CAJA_OPCAJA`,`fza_caja_operaciones`.`NUMERO_OPERACION_OPCAJA`) `o` on(`o`.`CODIGO_EMP_OPCAJA` = `p`.`CODIGO_EMP_PAGO` and `o`.`CODIGO_ALM_OPCAJA` = `p`.`CODIGO_ALM_PAGO` and `o`.`CODIGO_CAJA_OPCAJA` = `p`.`CODIGO_CAJA_PAGO` and `o`.`NUMERO_OPERACION_OPCAJA` = `p`.`NUMERO_OPERACION_PAGO`));

-- Vista: vi_caja_tarifa_sku_articulos
DROP TABLE IF EXISTS `vi_caja_tarifa_sku_articulos`;
DROP VIEW IF EXISTS `vi_caja_tarifa_sku_articulos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_caja_tarifa_sku_articulos` AS select `skus`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_ARTTAR`,`skus`.`CODIGO_ART_SKU` AS `CODIGO_ART_ART`,`tarifas`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR`,`tarifas`.`NOMBRE_TAR_TAR` AS `NOMBRE_TAR_TAR`,coalesce(`tarifa_sku`.`PRECIO_FINAL_ARTTAR`,`tarifa_padre`.`PRECIO_FINAL_ARTTAR`) AS `PRECIO_FINAL_ARTTAR`,coalesce(`tarifa_sku`.`PRECIO_SALIDA_ARTTAR`,`tarifa_padre`.`PRECIO_SALIDA_ARTTAR`) AS `PRECIO_SALIDA_ARTTAR`,coalesce(`tarifa_sku`.`PORCENTAJE_DTO_ARTTAR`,`tarifa_padre`.`PORCENTAJE_DTO_ARTTAR`) AS `PORCENTAJE_DTO_ARTTAR`,coalesce(`tarifa_sku`.`PRECIO_DTO_ARTTAR`,`tarifa_padre`.`PRECIO_DTO_ARTTAR`) AS `PRECIO_DTO_ARTTAR`,case when `tarifa_sku`.`PRECIO_FINAL_ARTTAR` is not null then 'ESPECIFICO_SKU' else 'HEREDADO_PADRE' end AS `ORIGEN_PRECIO`,concat(`articulos`.`DESCRIPCION_ART`,' (',`skus`.`CODIGO_UNIDAD_SKU`,')') AS `DESCRIPCION_COMPLETA`,`tarifas`.`ESIMP_INCL_TAR` AS `ESIMP_INCL_TAR`,`articulos`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`articulos`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART` from (((((`fza_articulos_skus` `skus` join `fza_articulos` `articulos` on(`skus`.`CODIGO_ART_SKU` = `articulos`.`CODIGO_ART_ART`)) join (select distinct `fza_articulos_tarifas`.`CODIGO_ART_ARTTAR` AS `CODIGO_ART_ARTTAR`,`fza_articulos_tarifas`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR` from `fza_articulos_tarifas`) `t_existentes` on(`t_existentes`.`CODIGO_ART_ARTTAR` = `articulos`.`CODIGO_ART_ART`)) join `fza_tarifas` `tarifas` on(`tarifas`.`CODIGO_TAR_ARTTAR` = `t_existentes`.`CODIGO_TAR_ARTTAR`)) left join `fza_articulos_tarifas` `tarifa_sku` on(`skus`.`CODIGO_UNIDAD_SKU` = `tarifa_sku`.`CODIGO_UNIDAD_ARTTAR` and `tarifas`.`CODIGO_TAR_ARTTAR` = `tarifa_sku`.`CODIGO_TAR_ARTTAR`)) left join `fza_articulos_tarifas` `tarifa_padre` on(`articulos`.`CODIGO_ART_ART` = `tarifa_padre`.`CODIGO_ART_ARTTAR` and `tarifas`.`CODIGO_TAR_ARTTAR` = `tarifa_padre`.`CODIGO_TAR_ARTTAR` and (`tarifa_padre`.`CODIGO_UNIDAD_ARTTAR` is null or `tarifa_padre`.`CODIGO_UNIDAD_ARTTAR` = ''))) where `skus`.`ESACTIVO_SKU` = 'S' and (`tarifa_sku`.`PRECIO_FINAL_ARTTAR` is not null or `tarifa_padre`.`PRECIO_FINAL_ARTTAR` is not null) order by `skus`.`CODIGO_ART_SKU`,`skus`.`CODIGO_UNIDAD_SKU`,`tarifas`.`ORDEN_TAR`;

-- Vista: vi_caja_totalventas
DROP TABLE IF EXISTS `vi_caja_totalventas`;
DROP VIEW IF EXISTS `vi_caja_totalventas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_caja_totalventas` AS select `fza_facturas`.`FECHA_FAC` AS `FECHA`,count(0) AS `TOTAL_VENTAS`,sum(`fza_facturas`.`TOTAL_LIQUIDO_FAC`) AS `TOTAL_COBRADO` from `fza_facturas` group by `fza_facturas`.`FECHA_FAC` order by `fza_facturas`.`FECHA_FAC`;

-- Vista: vi_caja_vales_ptes
DROP TABLE IF EXISTS `vi_caja_vales_ptes`;
DROP VIEW IF EXISTS `vi_caja_vales_ptes`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_caja_vales_ptes` AS select `fza_caja_vales`.`CODIGO_VL` AS `codigo_vale`,`fza_caja_vales`.`PIN_SEGURIDAD_VL` AS `pin`,`fza_caja_vales`.`IMPORTE_NOMINAL_VL` AS `importe`,`fza_caja_vales`.`FECHA_EMISION_VL` AS `fecha_emision`,`fza_caja_vales`.`FECHA_CADUCIDAD_VL` AS `fecha_caducidad`,`fza_caja_vales`.`CODIGO_CAJA_EMI_VL` AS `caja`,`fza_caja_vales`.`CODIGO_ALM_EMI_VL` AS `almacen`,`fza_caja_vales`.`NUMERO_OPERACION_EMI_VL` AS `num_operacion`,`fza_caja_vales`.`SERIE_FAC_EMI_VL` AS `serie_factura`,`fza_caja_vales`.`NUMERO_FAC_EMI_VL` AS `num_factura`,`fza_caja_vales`.`CODIGO_CLI_VL` AS `cliente`,`fza_caja_vales`.`OBSERVACIONES_VL` AS `observaciones`,to_days(`fza_caja_vales`.`FECHA_CADUCIDAD_VL`) - to_days(curdate()) AS `dias_hasta_caducidad` from `fza_caja_vales` where `fza_caja_vales`.`ESTADO_VL` = 'PENDIENTE' and (`fza_caja_vales`.`FECHA_CADUCIDAD_VL` is null or `fza_caja_vales`.`FECHA_CADUCIDAD_VL` >= curdate()) order by `fza_caja_vales`.`FECHA_EMISION_VL` desc;

-- Vista: vi_cajasdef
DROP TABLE IF EXISTS `vi_cajasdef`;
DROP VIEW IF EXISTS `vi_cajasdef`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_cajasdef` AS select `e`.`CODIGO_EMP_EMP` AS `Empresa`,`e`.`RAZON_SOCIAL_EMP` AS `NombreEmpresa`,`a`.`CODIGO_ALM_ALM` AS `Almacen`,`a`.`NOMBRE_ALM_ALM` AS `NombreAlmacén`,`c`.`CODIGO_CAJA_ALMCAJ` AS `Caja`,`c`.`DESCRIPCION_ALMCAJ` AS `NombreCaja` from ((`fza_empresas` `e` join `fza_almacenes` `a` on(`e`.`CODIGO_EMP_EMP` = `a`.`CODIGO_EMP_ALM`)) join `fza_almacenes_cajas` `c` on(`a`.`CODIGO_ALM_ALM` = `c`.`CODIGO_ALM_ALMCAJ`)) where `e`.`ESACTIVO_EMP` = 'S' and `a`.`ESACTIVO_ALM` = 'S';

