 AS `T07`,coalesce(sum(case when `p`.`POSICION` = 8 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T08`,coalesce(sum(case when `p`.`POSICION` = 9 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T09`,coalesce(sum(case when `p`.`POSICION` = 10 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T10`,coalesce(sum(case when `p`.`POSICION` = 11 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T11`,coalesce(sum(case when `p`.`POSICION` = 12 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T12`,coalesce(sum(case when `p`.`POSICION` = 13 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T13`,coalesce(sum(case when `p`.`POSICION` = 14 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T14`,coalesce(sum(case when `p`.`POSICION` = 15 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T15`,coalesce(sum(case when `p`.`POSICION` = 16 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T16`,coalesce(sum(case when `p`.`POSICION` = 17 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T17`,coalesce(sum(case when `p`.`POSICION` = 18 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T18`,coalesce(sum(case when `p`.`POSICION` = 19 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T19`,coalesce(sum(case when `p`.`POSICION` = 20 then `cel`.`CANTIDAD_SESCEL` end),0) AS `T20` from (((((`fza_compras_sesiones_lineas` `lin` join `fza_compras_sesiones` `ses` on(`ses`.`SERIE_SES` = `lin`.`SERIE_SES_SESLIN` and `ses`.`NUMERO_SES` = `lin`.`NUMERO_SES_SESLIN`)) left join `fza_atributos_conjuntos` `ac` on(`ac`.`ID_AC` = `lin`.`ID_AC_PIVOT_SESLIN`)) left join `fza_compras_sesiones_celdas` `cel` on(`cel`.`SERIE_SES_SESCEL` = `lin`.`SERIE_SES_SESLIN` and `cel`.`NUMERO_SES_SESCEL` = `lin`.`NUMERO_SES_SESLIN` and `cel`.`LINEA_SES_SESCEL` = `lin`.`LINEA_SESLIN`)) left join `pos_acd` `p` on(`p`.`ID_AC` = `lin`.`ID_AC_PIVOT_SESLIN` and `p`.`ID_AV` = `cel`.`ID_AV_PIVOT_SESCEL`)) left join `fza_almacenes` `alm` on(`alm`.`CODIGO_ALM_ALM` = ifnull(nullif(`cel`.`CODIGO_ALM_SESCEL`,''),`ses`.`CODIGO_ALM_SES`))) group by `lin`.`SERIE_SES_SESLIN`,`lin`.`NUMERO_SES_SESLIN`,`lin`.`LINEA_SESLIN`,`lin`.`CODIGO_ART_TENTATIVO_SESLIN`,`lin`.`REF_PRV_SESLIN`,`lin`.`DESCRIPCION_SESLIN`,`lin`.`COLOR_TEXTO_SESLIN`,`lin`.`CODIGO_ATB_COLOR_SESLIN`,`lin`.`PRECIO_COMPRA_SESLIN`,`lin`.`PRECIO_VENTA_SESLIN`,`lin`.`ID_AC_PIVOT_SESLIN`,`ac`.`NOMBRE_AC`,`ac`.`NOMBRE_CORTO_AC`,ifnull(nullif(`cel`.`CODIGO_ALM_SESCEL`,''),`ses`.`CODIGO_ALM_SES`),`alm`.`NOMBRE_ALM_ALM`;

