UIDO_FACC` AS `TOTAL_LIQUIDO_FACTURA_VIEW_EFEC`,`prv`.`NOMBRE_PRV` AS `NOMBRE_PRV_VIEW_EFEC`,`t`.`DESCRIPCION_TEFE` AS `DESCRIPCION_TEFE_VIEW_EFEC` from (((`fza_efectos_compra` `e` left join `fza_facturas_compra` `f` on(`f`.`SERIE_FACC` = `e`.`SERIE_FACC_EFEC` and `f`.`NUMERO_FACC` = `e`.`NUMERO_FACC_EFEC`)) left join `fza_proveedores` `prv` on(`prv`.`CODIGO_PRV_PRV` = `e`.`CODIGO_PRV_EFEC`)) left join `fza_tipos_efecto` `t` on(`t`.`CODIGO_TEFE` = `e`.`CODIGO_TEFE_EFEC`));

