-- Vista: vi_empresas_series
DROP TABLE IF EXISTS `vi_empresas_series`;
DROP VIEW IF EXISTS `vi_empresas_series`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_empresas_series` AS select `s`.`CODIGO_SERIE_EMPSER` AS `CODIGO_SERIE_EMPSER`,`s`.`CODIGO_EMP_EMPSER` AS `CODIGO_EMP_EMPSER`,`s`.`CODIGO_ALM_EMPSER` AS `CODIGO_ALM_EMPSER`,`s`.`CODIGO_CAJA_EMPSER` AS `CODIGO_CAJA_EMPSER`,case when `e`.`ESTOKENS_CALENDARIO_NATURAL_EMP` = 'S' and nullif(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'') is not null and char_length(trim(`s`.`SERIE_TOKENIZADA_EMPSER`)) - char_length(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'yyyy','')) in (0,4) and char_length(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'yyyy','')) - char_length(replace(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'yyyy',''),'yy','')) in (0,2) and char_length(trim(`s`.`SERIE_TOKENIZADA_EMPSER`)) - char_length(replace(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'yyyy',''),'yy','')) in (0,2,4) and char_length(trim(`s`.`SERIE_TOKENIZADA_EMPSER`)) - char_length(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'q','')) in (0,1) and char_length(trim(`s`.`SERIE_TOKENIZADA_EMPSER`)) - char_length(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'mm','')) in (0,2) and char_length(trim(`s`.`SERIE_TOKENIZADA_EMPSER`)) - char_length(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'dd','')) in (0,2) and (locate(cast('yy' as char charset binary),cast(trim(`s`.`SERIE_TOKENIZADA_EMPSER`) as char charset binary)) > 0 or locate(cast('q' as char charset binary),cast(trim(`s`.`SERIE_TOKENIZADA_EMPSER`) as char charset binary)) > 0 or locate(cast('mm' as char charset binary),cast(trim(`s`.`SERIE_TOKENIZADA_EMPSER`) as char charset binary)) > 0 or locate(cast('dd' as char charset binary),cast(trim(`s`.`SERIE_TOKENIZADA_EMPSER`) as char charset binary)) > 0) then replace(replace(replace(replace(replace(trim(`s`.`SERIE_TOKENIZADA_EMPSER`),'yyyy',cast(year(curdate()) as char charset utf8mb4)),'yy',date_format(curdate(),'%y')),'mm',date_format(curdate(),'%m')),'dd',date_format(curdate(),'%d')),'q',cast(quarter(curdate()) as char charset utf8mb4)) else `s`.`EMPSER` end AS `EMPSER`,`s`.`SERIE_TOKENIZADA_EMPSER` AS `SERIE_TOKENIZADA_EMPSER`,`s`.`TIPO_DOC_EMPSER` AS `TIPO_DOC_EMPSER`,`s`.`SUBTIPO_EMPSER` AS `SUBTIPO_EMPSER`,`s`.`FECHA_DESDE_EMPSER` AS `FECHA_DESDE_EMPSER`,`s`.`FECHA_HASTA_EMPSER` AS `FECHA_HASTA_EMPSER`,`s`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`s`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`s`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`s`.`USUARIO_MODIF` AS `USUARIO_MODIF` from (`fza_empresas_series` `s` left join `fza_empresas` `e` on(`e`.`CODIGO_EMP_EMP` = `s`.`CODIGO_EMP_EMPSER`));

