DROP VIEW IF EXISTS `vi_facturas_compra_cab_print`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_facturas_compra_cab_print` AS select `fac`.`SERIE_FACC` AS `SERIE_FACC`,`fac`.`NUMERO_FACC` AS `NUMERO_FACC`,case when trim(coalesce(`fac`.`SERIE_FACC`,'')) = '' then trim(coalesce(`fac`.`NUMERO_FACC`,'')) when trim(coalesce(`fac`.`NUMERO_FACC`,'')) = '' then trim(coalesce(`fac`.`SERIE_FACC`,'')) else concat(trim(coalesce(`fac`.`SERIE_FACC`,'')),'.',trim(coalesce(`fac`.`NUMERO_FACC`,''))) end AS `DOCUMENTO_FORMATO`,`fac`.`FECHA_FACC` AS `FECHA_FACC`,`fac`.`ESTADO_FACC` AS `ESTADO_FACC`,`fac`.`REF_PROVEEDOR_FACC` AS `REF_PROVEEDOR_FACC`,`fac`.`COMENTARIOS_FACC` AS `COMENTARIOS_FACC`,`fac`.`OBSERVACIONES_FACC` AS `OBSERVACIONES_FACC`,`fac`.`CODIGO_EMP_FACC` AS `CODIGO_EMP_FACC`,`emp`.`RAZON_SOCIAL_EMP` AS `RAZON_SOCIAL_EMP`,`emp`.`DIRECCION1_EMP` AS `DIRECCION1_EMP`,`emp`.`CODIGO_POSTAL_EMP` AS `CODIGO_POSTAL_EMP`,`emp`.`POBLACION_EMP` AS `POBLACION_EMP`,`emp`.`PROVINCIA_EMP` AS `PROVINCIA_EMP`,`emp`.`NIF_EMP` AS `CIF_EMP`,`emp`.`MOVIL_EMP` AS `TELEFONO1_EMP`,`fac`.`CODIGO_PRV_FACC` AS `CODIGO_PRV_FACC`,`prv`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`prv`.`DIRECCION1_PRV` AS `DIRECCION1_PRV`,`prv`.`CODIGO_POSTAL_PRV` AS `CODIGO_POSTAL_PRV`,`prv`.`POBLACION_PRV` AS `POBLACION_PRV`,`prv`.`PROVINCIA_PRV` AS `PROVINCIA_PRV`,`prv`.`NIF_PRV` AS `CIF_PRV`,coalesce(`prv`.`TELEFONO_PRV`,`prv`.`MOVIL_PRV`) AS `TELEFONO1_PRV`,`fac`.`CODIGO_ALM_FACC` AS `CODIGO_ALM_FACC`,`alm`.`NOMBRE_ALM_ALM` AS `NOMBRE_ALM_FACC`,`alm`.`DIRECCION_ALM` AS `DIRECCION_ALM_FACC`,`alm`.`CODIGO_POSTAL_ALM` AS `CODIGO_POSTAL_ALM_FACC`,`alm`.`POBLACION_ALM` AS `POBLACION_ALM_FACC`,`alm`.`PROVINCIA_ALM` AS `PROVINCIA_ALM_FACC`,`alm`.`TELEFONO_ALM` AS `TELEFONO_ALM_FACC`,`alm`.`EMAIL_ALM` AS `EMAIL_ALM_FACC`,`fac`.`CODIGO_IVA_FACC` AS `CODIGO_IVA_FACC`,`fac`.`ESIVA_RECARGO_COMPRAS_FACC` AS `ESIVA_RECARGO_COMPRAS_FACC`,`fac`.`PORCENTAJE_IVAN_FACC` AS `PORCENTAJE_IVAN_FACC`,`fac`.`TOTAL_BASEI_IVAN_FACC` AS `TOTAL_BASEI_IVAN_FACC`,`fac`.`TOTAL_IVAN_FACC` AS `TOTAL_IVAN_FACC`,`fac`.`PORCENTAJE_REN_FACC` AS `PORCENTAJE_REN_FACC`,`fac`.`TOTAL_REN_FACC` AS `TOTAL_REN_FACC`,`fac`.`PORCENTAJE_IVAR_FACC` AS `PORCENTAJE_IVAR_FACC`,`fac`.`TOTAL_BASEI_IVAR_FACC` AS `TOTAL_BASEI_IVAR_FACC`,`fac`.`TOTAL_IVAR_FACC` AS `TOTAL_IVAR_FACC`,`fac`.`PORCENTAJE_RER_FACC` AS `PORCENTAJE_RER_FACC`,`fac`.`TOTAL_RER_FACC` AS `TOTAL_RER_FACC`,`fac`.`PORCENTAJE_IVAS_FACC` AS `PORCENTAJE_IVAS_FACC`,`fac`.`TOTAL_BASEI_IVAS_FACC` AS `TOTAL_BASEI_IVAS_FACC`,`fac`.`TOTAL_IVAS_FACC` AS `TOTAL_IVAS_FACC`,`fac`.`PORCENTAJE_RES_FACC` AS `PORCENTAJE_RES_FACC`,`fac`.`TOTAL_RES_FACC` AS `TOTAL_RES_FACC`,`fac`.`PORCENTAJE_IVAE_FACC` AS `PORCENTAJE_IVAE_FACC`,`fac`.`TOTAL_BASEI_IVAE_FACC` AS `TOTAL_BASEI_IVAE_FACC`,`fac`.`TOTAL_IVAE_FACC` AS `TOTAL_IVAE_FACC`,`fac`.`PORCENTAJE_REE_FACC` AS `PORCENTAJE_REE_FACC`,`fac`.`TOTAL_REE_FACC` AS `TOTAL_REE_FACC`,`fac`.`PORCENTAJE_RETENCION_FACC` AS `PORCENTAJE_RETENCION_FACC`,`fac`.`TOTAL_RETENCION_FACC` AS `TOTAL_RETENCION_FACC`,`fac`.`TOTAL_BASES_FACC` AS `TOTAL_BASES_FACC`,`fac`.`TOTAL_IMPUESTOS_FACC` AS `TOTAL_IMPUESTOS_FACC`,`fac`.`TOTAL_LIQUIDO_FACC` AS `TOTAL_LIQUIDO_FACC`,`fac`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fac`.`USUARIO_ALTA` AS `USUARIO_ALTA`,(select coalesce(sum(`lin`.`CANTIDAD_FACCLIN`),0) from `fza_facturas_compra_lineas` `lin` where `lin`.`SERIE_FACC_FACCLIN` = `fac`.`SERIE_FACC` and `lin`.`NUMERO_FACC_FACCLIN` = `fac`.`NUMERO_FACC`) AS `TOTAL_UNIDADES_FACC`,(select coalesce(sum(`lin`.`TOTAL_FACCLIN`),0) from `fza_facturas_compra_lineas` `lin` where `lin`.`SERIE_FACC_FACCLIN` = `fac`.`SERIE_FACC` and `lin`.`NUMERO_FACC_FACCLIN` = `fac`.`NUMERO_FACC`) AS `TOTAL_LINEAS_FACC`,(select count(0) from `fza_facturas_compra_lineas` `lin` where `lin`.`SERIE_FACC_FACCLIN` = `fac`.`SERIE_FACC` and `lin`.`NUMERO_FACC_FACCLIN` = `fac`.`NUMERO_FACC`) AS `NUM_LINEAS_FACC` from (((`fza_facturas_compra` `fac` left join `fza_empresas` `emp` on(`emp`.`CODIGO_EMP_EMP` = `fac`.`CODIGO_EMP_FACC`)) left join `fza_proveedores` `prv` on(`prv`.`CODIGO_PRV_PRV` = `fac`.`CODIGO_PRV_FACC`)) left join `fza_almacenes` `alm` on(`alm`.`CODIGO_ALM_ALM` = `fac`.`CODIGO_ALM_FACC`));

-- Vista: vi_facturas_compra_guias_print
DROP TABLE IF EXISTS `vi_facturas_compra_guias_print`;
DROP VIEW IF EXISTS `vi_facturas_compra_guias_print`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_facturas_compra_guias_print` AS with pos_acd as (select `acd`.`ID_AC_ACD` AS `ID_AC`,`acd`.`ID_AV_ACD` AS `ID_AV`,`av`.`AV` AS `AV`,row_number() over ( partition by `acd`.`ID_AC_ACD` order by `acd`.`ORDEN_ACD`,`acd`.`ID_AV_ACD`) AS `POSICION` from (`fza_atributos_conjuntos_det` `acd` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `acd`.`ID_AV_ACD`)))select `ac`.`ID_AC` AS `ID_AC`,`ac`.`NOMBRE_AC` AS `NOMBRE_AC`,coalesce(`ac`.`NOMBRE_CORTO_AC`,ucase(left(`ac`.`NOMBRE_AC`,8))) AS `NOMBRE_CORTO_AC`,max(case when `p`.`POSICION` = 1 then `p`.`AV` end) AS `T01`,max(case when `p`.`POSICION` = 2 then `p`.`AV` end) AS `T02`,max(case when `p`.`POSICION` = 3 then `p`.`AV` end) AS `T03`,max(case when `p`.`POSICION` = 4 then `p`.`AV` end) AS `T04`,max(case when `p`.`POSICION` = 5 then `p`.`AV` end) AS `T05`,max(case when `p`.`POSICION` = 6 then `p`.`AV` end) AS `T06`,max(case when `p`.`POSICION` = 7 then `p`.`AV` end) AS `T07`,max(case when `p`.`POSICION` = 8 then `p`.`AV` end) AS `T08`,max(case when `p`.`POSICION` = 9 then `p`.`AV` end) AS `T09`,max(case when `p`.`POSICION` = 10 then `p`.`AV` end) AS `T10`,max(case when `p`.`POSICION` = 11 then `p`.`AV` end) AS `T11`,max(case when `p`.`POSICION` = 12 then `p`.`AV` end) AS `T12`,max(case when `p`.`POSICION` = 13 then `p`.`AV` end) AS `T13`,max(case when `p`.`POSICION` = 14 then `p`.`AV` end) AS `T14`,max(case when `p`.`POSICION` = 15 then `p`.`AV` end) AS `T15`,max(case when `p`.`POSICION` = 16 then `p`.`AV` end) AS `T16`,max(case when `p`.`POSICION` = 17 then `p`.`AV` end) AS `T17`,max(case when `p`.`POSICION` = 18 then `p`.`AV` end) AS `T18`,max(case when `p`.`POSICION` = 19 then `p`.`AV` end) AS `T19`,max(case when `p`.`POSICION` = 20 then `p`.`AV` end) AS `T20` from (`fza_atributos_conjuntos` `ac` join `pos_acd` `p` on(`p`.`ID_AC` = `ac`.`ID_AC`)) where `p`.`POSICION` <= 20 and `ac`.`ESACTIVO_AC` = 'S' group by `ac`.`ID_AC`,`ac`.`NOMBRE_AC`,`ac`.`NOMBRE_CORTO_AC`;

-- Vista: vi_facturas_compra_lin_print
DROP TABLE IF EXISTS `vi_facturas_compra_lin_print`;
DROP VIEW IF EXISTS `vi_facturas_compra_lin_print`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_facturas_compra_lin_print` AS with pos_acd as (select `fza_atributos_conjuntos_det`.`ID_AC_ACD` AS `ID_AC`,`fza_atributos_conjuntos_det`.`ID_AV_ACD` AS `ID_AV`,row_number() over ( partition by `fza_atributos_conjuntos_det`.`ID_AC_ACD` order by `fza_atributos_conjuntos_det`.`ORDEN_ACD`,`fza_atributos_conjuntos_det`.`ID_AV_ACD`) AS `POSICION` from `fza_atributos_conjuntos_det`), sku_talla as (select `sa`.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,`sa`.`ID_AV_SA` AS `ID_AV_TALLA` from (`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA` and `av`.`ID_VA_AV` = 'TAL'))), sku_color as (select `sa`.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,`atb`.`CODIGO_ATB` AS `CODIGO_ATB_COLOR`,`atb`.`NOMBRE_ATB` AS `NOMBRE_COLOR` from ((`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA` and `av`.`ID_VA_AV` = 'CO')) left join `fza_atributos_basicos` `atb` on(`atb`.`ID_ATB` = `av`.`ID_ATB_AV`)))select `l`.`SERIE_FACC_FACCLIN` AS `SERIE_FACC`,`l`.`NUMERO_FACC_FACCLIN` AS `NUMERO_FACC`,min(`l`.`LINEA_FACCLIN`) AS `LINEA_FACC`,`l`.`CODIGO_ART_FACCLIN` AS `CODIGO_ART`,coalesce(min(`l`.`REF_PRV_FACCLIN`),'') AS `REF_PRV`,min(`l`.`DESCRIPCION_ARTICULO_FACCLIN`) AS `DESCRIPCION`,coalesce(min(`sc`.`NOMBRE_COLOR`),substring_index(substring_index(min(`l`.`CODIGO_UNIDAD_FACCLIN`),'/',2),'/',-1),'') AS `COLOR_TEXTO`,coalesce(min(`sc`.`CODIGO_ATB_COLOR`),'') AS `CODIGO_ATB_COLOR`,avg(`l`.`PRECIO_COMPRA_SIVA_ARTICULO_FACCLIN`) AS `PRECIO_COMPRA`,0 AS `PRECIO_VENTA`,`l`.`ID_AC_PIVOT_FACCLIN` AS `ID_AC_PIVOT`,`ac`.`NOMBRE_AC` AS `NOMBRE_AC`,coalesce(`ac`.`NOMBRE_CORTO_AC`,ucase(left(`ac`.`NOMBRE_AC`,8))) AS `NOMBRE_CORTO_AC`,`l`.`CODIGO_ALMACEN_FACCLIN` AS `CODIGO_ALM_FACCLIN`,min(`alm`.`CODIGO_EMP_ALM`) AS `CODIGO_EMP_ALM_FACCLIN`,min(`alm`.`NOMBRE_ALM_ALM`) AS `NOMBRE_ALM_FACCLIN`,min(`alm`.`DIRECCION_ALM`) AS `DIRECCION_ALM_FACCLIN`,min(`alm`.`CODIGO_POSTAL_ALM`) AS `CODIGO_POSTAL_ALM_FACCLIN`,min(`alm`.`POBLACION_ALM`) AS `POBLACION_ALM_FACCLIN`,min(`alm`.`PROVINCIA_ALM`) AS `PROVINCIA_ALM_FACCLIN`,min(`alm`.`TELEFONO_ALM`) AS `TELEFONO_ALM_FACCLIN`,min(`alm`.`EMAIL_ALM`) AS `EMAIL_ALM_FACCLIN`,sum(`l`.`CANTIDAD_FACCLIN`) AS `TOTAL_UNIDADES`,sum(`l`.`TOTAL_FACCLIN`) AS `TOTAL_LINEA`,coalesce(sum(case when `p`.`POSICION` = 1 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T01`,coalesce(sum(case when `p`.`POSICION` = 2 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T02`,coalesce(sum(case when `p`.`POSICION` = 3 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T03`,coalesce(sum(case when `p`.`POSICION` = 4 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T04`,coalesce(sum(case when `p`.`POSICION` = 5 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T05`,coalesce(sum(case when `p`.`POSICION` = 6 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T06`,coalesce(sum(case when `p`.`POSICION` = 7 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T07`,coalesce(sum(case when `p`.`POSICION` = 8 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T08`,coalesce(sum(case when `p`.`POSICION` = 9 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T09`,coalesce(sum(case when `p`.`POSICION` = 10 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T10`,coalesce(sum(case when `p`.`POSICION` = 11 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T11`,coalesce(sum(case when `p`.`POSICION` = 12 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T12`,coalesce(sum(case when `p`.`POSICION` = 13 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T13`,coalesce(sum(case when `p`.`POSICION` = 14 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T14`,coalesce(sum(case when `p`.`POSICION` = 15 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T15`,coalesce(sum(case when `p`.`POSICION` = 16 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T16`,coalesce(sum(case when `p`.`POSICION` = 17 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T17`,coalesce(sum(case when `p`.`POSICION` = 18 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T18`,coalesce(sum(case when `p`.`POSICION` = 19 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T19`,coalesce(sum(case when `p`.`POSICION` = 20 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T20` from (((((`fza_facturas_compra_lineas` `l` left join `fza_atributos_conjuntos` `ac` on(`ac`.`ID_AC` = `l`.`ID_AC_PIVOT_FACCLIN`)) left join `sku_talla` `st` on(`st`.`CODIGO_UNIDAD` = `l`.`CODIGO_UNIDAD_FACCLIN`)) left join `pos_acd` `p` on(`p`.`ID_AC` = `l`.`ID_AC_PIVOT_FACCLIN` and `p`.`ID_AV` = `st`.`ID_AV_TALLA`)) left join `sku_color` `sc` on(`sc`.`CODIGO_UNIDAD` = `l`.`CODIGO_UNIDAD_FACCLIN`)) left join `fza_almacenes` `alm` on(`alm`.`CODIGO_ALM_ALM` = `l`.`CODIGO_ALMACEN_FACCLIN`)) group by `l`.`SERIE_FACC_FACCLIN`,`l`.`NUMERO_FACC_FACCLIN`,`l`.`CODIGO_ART_FACCLIN`,`l`.`ID_AC_PIVOT_FACCLIN`,`ac`.`NOMBRE_AC`,`ac`.`NOMBRE_CORTO_AC`,`sc`.`CODIGO_ATB_COLOR`,`sc`.`NOMBRE_COLOR`,substring_index(substring_index(`l`.`CODIGO_UNIDAD_FACCLIN`,'/',2),'/',-1),`l`.`CODIGO_ALMACEN_FACCLIN`;

-- Vista: vi_facturas_lineas
DROP TABLE IF EXISTS `vi_facturas_lineas`;
DROP VIEW IF EXISTS `vi_facturas_lineas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_facturas_lineas` AS select `fl`.`NUMERO_FAC_FACLIN` AS `NUMERO_FAC_FACLIN`,`fl`.`SERIE_FAC_FACLIN` AS `SERIE_FAC_FACLIN`,`fl`.`CODIGO_EMP_FACLIN` AS `CODIGO_EMP_FACLIN`,`fl`.`LINEA_FACLIN` AS `LINEA_FACLIN`,`fl`.`CODIGO_ART_FACLIN` AS `CODIGO_ART_FACLIN`,`fl`.`CODIGO_UNIDAD_FACLIN` AS `CODIGO_UNIDAD_FACLIN`,`fl`.`LOTE_FACLIN` AS `LOTE_FACLIN`,`fl`.`FECHA_CADUCIDAD_FACLIN` AS `FECHA_CADUCIDAD_FACLIN`,`fl`.`CODIGO_FAM_FACLIN` AS `CODIGO_FAM_FACLIN`,`fl`.`NOMBRE_FAM_FACLIN` AS `NOMBRE_FAM_FACLIN`,`fl`.`PRECIO_ULT_COMPRA_FACLIN` AS `PRECIO_ULT_COMPRA_FACLIN`,`fl`.`CODIGO_PRV_FACLIN` AS `CODIGO_PRV_FACLIN`,`fl`.`RAZON_SOCIAL_PROVEEDOR_FACLIN` AS `RAZON_SOCIAL_PROVEEDOR_FACLIN`,`fl`.`ESPROVEEDORPRINCIPAL_FACLIN` AS `ESPROVEEDORPRINCIPAL_FACLIN`,`fl`.`FECHA_ENTREGA_FACLIN` AS `FECHA_ENTREGA_FACLIN`,`fl`.`TIPO_ARTICULO_FACLIN` AS `TIPO_ARTICULO_FACLIN`,`fl`.`TIPO_CANTIDAD_ARTICULO_FACLIN` AS `TIPO_CANTIDAD_ARTICULO_FACLIN`,`fl`.`CANTIDAD_FACLIN` AS `CANTIDAD_FACLIN`,`fl`.`DESCRIPCION_ARTICULO_FACLIN` AS `DESCRIPCION_ARTICULO_FACLIN`,`fl`.`DESCRIPCION_VARIACION_FACLIN` AS `DESCRIPCION_VARIACION_FACLIN`,`fl`.`CODIGO_TAR_FACLIN` AS `CODIGO_TAR_FACLIN`,`fl`.`ESIMP_INCL_TARIFA_FACLIN` AS `ESIMP_INCL_TARIFA_FACLIN`,`fl`.`PRECIO_SALIDA_FACLIN` AS `PRECIO_SALIDA_FACLIN`,`fl`.`PORCENTAJE_DTO_FACLIN` AS `PORCENTAJE_DTO_FACLIN`,`fl`.`PRECIO_DTO_FACLIN` AS `PRECIO_DTO_FACLIN`,`fl`.`PRECIO_VENTA_SIVA_ARTICULO_FACLIN` AS `PRECIO_VENTA_SIVA_ARTICULO_FACLIN`,`fl`.`TIPO_IVA_ARTICULO_FACLIN` AS `TIPO_IVA_ARTICULO_FACLIN`,`fl`.`PORCENTAJE_IVA_FACLIN` AS `PORCENTAJE_IVA_FACLIN`,`fl`.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN` AS `PRECIO_VENTA_CIVA_ARTICULO_FACLIN`,`fl`.`TOTAL_FACLIN` AS `TOTAL_FACLIN`,`fl`.`TOTAL_FAC_SIVA_FACLIN` AS `TOTAL_FAC_SIVA_FACLIN`,`fl`.`CODIGO_VENDEDOR_FACLIN` AS `CODIGO_VENDEDOR_FACLIN`,`fl`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fl`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fl`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fl`.`USUARIO_MODIF` AS `USUARIO_MODIF`,`fl`.`CODIGO_ALM_FACLIN` AS `CODIGO_ALM_FACLIN`,`fl`.`CODIGO_CAJA_FACLIN` AS `CODIGO_CAJA_FACLIN`,`fl`.`NUMERO_OPERACION_FACLIN` AS `NUMERO_OPERACION_FACLIN`,`fl`.`NUMERO_MOV_FACLIN` AS `NUMERO_MOV_FACLIN`,`fl`.`ATTR1_VALOR_FACLIN` AS `ATTR1_VALOR_FACLIN`,`fl`.`ATTR1_NOMBRE_FACLIN` AS `ATTR1_NOMBRE_FACLIN`,`fl`.`ATTR2_VALOR_FACLIN` AS `ATTR2_VALOR_FACLIN`,`fl`.`ATTR2_NOMBRE_FACLIN` AS `ATTR2_NOMBRE_FACLIN`,`fl`.`ATTR3_VALOR_FACLIN` AS `ATTR3_VALOR_FACLIN`,`fl`.`ATTR3_NOMBRE_FACLIN` AS `ATTR3_NOMBRE_FACLIN`,`fl`.`ATTR4_VALOR_FACLIN` AS `ATTR4_VALOR_FACLIN`,`fl`.`ATTR4_NOMBRE_FACLIN` AS `ATTR4_NOMBRE_FACLIN`,`fl`.`ATTR5_VALOR_FACLIN` AS `ATTR5_VALOR_FACLIN`,`fl`.`ATTR5_NOMBRE_FACLIN` AS `ATTR5_NOMBRE_FACLIN`,`fl`.`NUM_ATRIBUTOS_FACLIN` AS `NUM_ATRIBUTOS_FACLIN` from `fza_facturas_lineas` `fl`;

-- Vista: vi_facturas_lineas_print
