CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_info_tpv_completa` AS select `a`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,`a`.`ESTRAZABLE_ART` AS `TIENE_TRAZABILIDAD`,(select count(0) from `vi_atributos_nombres` `n` where `n`.`CODIGO_ART_PADRE_ARTVIN` = `a`.`CODIGO_ART_ART`) AS `NUM_ATRIBUTOS_REQ`,(select `n`.`NOMBRE_ATRIBUTO` from `vi_atributos_nombres` `n` where `n`.`CODIGO_ART_PADRE_ARTVIN` = `a`.`CODIGO_ART_ART` and `n`.`ORDEN_VISUAL_ATRIBUTO` = 1 limit 1) AS `ATTR1_NOMBRE`,(select `n`.`NOMBRE_ATRIBUTO` from `vi_atributos_nombres` `n` where `n`.`CODIGO_ART_PADRE_ARTVIN` = `a`.`CODIGO_ART_ART` and `n`.`ORDEN_VISUAL_ATRIBUTO` = 2 limit 1) AS `ATTR2_NOMBRE`,(select `n`.`NOMBRE_ATRIBUTO` from `vi_atributos_nombres` `n` where `n`.`CODIGO_ART_PADRE_ARTVIN` = `a`.`CODIGO_ART_ART` and `n`.`ORDEN_VISUAL_ATRIBUTO` = 3 limit 1) AS `ATTR3_NOMBRE`,(select `n`.`NOMBRE_ATRIBUTO` from `vi_atributos_nombres` `n` where `n`.`CODIGO_ART_PADRE_ARTVIN` = `a`.`CODIGO_ART_ART` and `n`.`ORDEN_VISUAL_ATRIBUTO` = 4 limit 1) AS `ATTR4_NOMBRE`,(select `n`.`NOMBRE_ATRIBUTO` from `vi_atributos_nombres` `n` where `n`.`CODIGO_ART_PADRE_ARTVIN` = `a`.`CODIGO_ART_ART` and `n`.`ORDEN_VISUAL_ATRIBUTO` = 5 limit 1) AS `ATTR5_NOMBRE` from `fza_articulos` `a`;

