CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_remesas_venta` AS select `r`.`NUMERO_REMV` AS `NUMERO_REMV`,`r`.`SERIE_REMV` AS `SERIE_REMV`,`r`.`FECHA_REMV` AS `FECHA_REMV`,`r`.`ESTADO_REMV` AS `ESTADO_REMV`,`r`.`CODIGO_EMP_REMV` AS `CODIGO_EMP_REMV`,`r`.`TIPO_REMV` AS `TIPO_REMV`,`r`.`NORMA_REMV` AS `NORMA_REMV`,`r`.`ENTIDAD_REMV` AS `ENTIDAD_REMV`,`r`.`OFICINA_REMV` AS `OFICINA_REMV`,`r`.`DIGITO_CONTROL_REMV` AS `DIGITO_CONTROL_REMV`,`r`.`CUENTA_REMV` AS `CUENTA_REMV`,`r`.`IBAN_REMV` AS `IBAN_REMV`,`r`.`CONTADOR_EFECTOS_REMV` AS `CONTADOR_EFECTOS_REMV`,`r`.`TOTAL_REMV` AS `TOTAL_REMV`,`r`.`TOTAL_GASTOS_REMV` AS `TOTAL_GASTOS_REMV`,`r`.`TOTAL_COMISION_REMV` AS `TOTAL_COMISION_REMV`,`r`.`FECHA_CARGO_REMV` AS `FECHA_CARGO_REMV`,`r`.`ARCHIVO_REMV` AS `ARCHIVO_REMV`,`r`.`OBSERVACIONES_REMV` AS `OBSERVACIONES_REMV`,`r`.`INSTANTE_CONTABILIZACION_REMV` AS `INSTANTE_CONTABILIZACION_REMV`,`r`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`r`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`r`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`r`.`USUARIO_MODIF` AS `USUARIO_MODIF`,`emp`.`RAZON_SOCIAL_EMP` AS `RAZON_SOCIAL_EMPRESA_VIEW_REMV` from (`fza_remesas_venta` `r` left join `fza_empresas` `emp` on(`emp`.`CODIGO_EMP_EMP` = `r`.`CODIGO_EMP_REMV`));

