-- Vista: vi_ses_preview_skus
DROP TABLE IF EXISTS `vi_ses_preview_skus`;
DROP VIEW IF EXISTS `vi_ses_preview_skus`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_ses_preview_skus` AS select `l`.`SERIE_SES_SESLIN` AS `SERIE`,`l`.`NUMERO_SES_SESLIN` AS `NUMERO`,`l`.`LINEA_SESLIN` AS `LINEA`,`l`.`CODIGO_ART_TENTATIVO_SESLIN` AS `CODIGO_ART`,`l`.`DESCRIPCION_SESLIN` AS `DESCRIPCION`,`c`.`ID_FILA_SES_SESCEL` AS `ID_FILA`,`c`.`ID_AV_PIVOT_SESCEL` AS `ID_AV_PIVOT`,`avp`.`AV` AS `VALOR_PIVOT`,if(`c`.`CODIGO_ALM_SESCEL` = '',`s`.`CODIGO_ALM_SES`,`c`.`CODIGO_ALM_SESCEL`) AS `CODIGO_ALM`,`c`.`CANTIDAD_SESCEL` AS `CANTIDAD`,`l`.`PRECIO_COMPRA_SESLIN` AS `PRECIO_COMPRA`,`l`.`PRECIO_VENTA_SESLIN` AS `PRECIO_VENTA` from (((`fza_compras_sesiones_lineas` `l` join `fza_compras_sesiones` `s` on(`s`.`SERIE_SES` = `l`.`SERIE_SES_SESLIN` and `s`.`NUMERO_SES` = `l`.`NUMERO_SES_SESLIN`)) join `fza_compras_sesiones_celdas` `c` on(`c`.`SERIE_SES_SESCEL` = `l`.`SERIE_SES_SESLIN` and `c`.`NUMERO_SES_SESCEL` = `l`.`NUMERO_SES_SESLIN` and `c`.`LINEA_SES_SESCEL` = `l`.`LINEA_SESLIN`)) join `fza_atributos_valores` `avp` on(`avp`.`ID_AV` = `c`.`ID_AV_PIVOT_SESCEL`)) where `c`.`CANTIDAD_SESCEL` > 0;

-- Vista: vi_ses_resumen
DROP TABLE IF EXISTS `vi_ses_resumen`;
DROP VIEW IF EXISTS `vi_ses_resumen`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_ses_resumen` AS select `s`.`SERIE_SES` AS `SERIE_SES`,`s`.`NUMERO_SES` AS `NUMERO_SES`,`s`.`FECHA_SES` AS `FECHA_SES`,`s`.`CODIGO_PRV_SES` AS `CODIGO_PRV_SES`,`s`.`CODIGO_FAM_SES` AS `CODIGO_FAM_SES`,`s`.`ESTADO_SES` AS `ESTADO_SES`,(select count(0) from `fza_compras_sesiones_lineas` `l` where `l`.`SERIE_SES_SESLIN` = `s`.`SERIE_SES` and `l`.`NUMERO_SES_SESLIN` = `s`.`NUMERO_SES`) AS `NUM_LINEAS`,(select count(0) from `fza_compras_sesiones_celdas` `c` where `c`.`SERIE_SES_SESCEL` = `s`.`SERIE_SES` and `c`.`NUMERO_SES_SESCEL` = `s`.`NUMERO_SES` and `c`.`CANTIDAD_SESCEL` > 0) AS `NUM_SKUS_POTENCIALES`,(select ifnull(sum(`l`.`TOTAL_LINEA_SESLIN`),0) from `fza_compras_sesiones_lineas` `l` where `l`.`SERIE_SES_SESLIN` = `s`.`SERIE_SES` and `l`.`NUMERO_SES_SESLIN` = `s`.`NUMERO_SES`) AS `TOTAL_COMPRA` from `fza_compras_sesiones` `s`;

-- Vista: vi_ses_resumen_almacen
DROP TABLE IF EXISTS `vi_ses_resumen_almacen`;
DROP VIEW IF EXISTS `vi_ses_resumen_almacen`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_ses_resumen_almacen` AS select `c`.`SERIE_SES_SESCEL` AS `SERIE`,`c`.`NUMERO_SES_SESCEL` AS `NUMERO`,if(`c`.`CODIGO_ALM_SESCEL` = '',`s`.`CODIGO_ALM_SES`,`c`.`CODIGO_ALM_SESCEL`) AS `CODIGO_ALM`,count(0) AS `NUM_SKUS`,sum(`c`.`CANTIDAD_SESCEL`) AS `UNIDADES_TOTAL` from (`fza_compras_sesiones_celdas` `c` join `fza_compras_sesiones` `s` on(`s`.`SERIE_SES` = `c`.`SERIE_SES_SESCEL` and `s`.`NUMERO_SES` = `c`.`NUMERO_SES_SESCEL`)) where `c`.`CANTIDAD_SESCEL` > 0 group by `c`.`SERIE_SES_SESCEL`,`c`.`NUMERO_SES_SESCEL`,if(`c`.`CODIGO_ALM_SESCEL` = '',`s`.`CODIGO_ALM_SES`,`c`.`CODIGO_ALM_SESCEL`);

-- Vista: vi_tarifas
DROP TABLE IF EXISTS `vi_tarifas`;
DROP VIEW IF EXISTS `vi_tarifas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_tarifas` AS select `fza_tarifas`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR`,`fza_tarifas`.`NOMBRE_TAR_TAR` AS `NOMBRE_TAR_TAR`,`fza_tarifas`.`ESACTIVO_ARTTAR` AS `ESACTIVO_ARTTAR`,`fza_tarifas`.`ORDEN_TAR` AS `ORDEN_TAR`,`fza_tarifas`.`ESIMP_INCL_TAR` AS `ESIMP_INCL_TAR`,`fza_tarifas`.`PORCENTAJE_MARGEN_TAR` AS `PORCENTAJE_MARGEN_TAR`,`fza_tarifas`.`VALOR_MULTIPLO_AJUSTE_TAR` AS `VALOR_MULTIPLO_AJUSTE_TAR`,`fza_tarifas`.`VALOR_MENOS_AJUSTE_TAR` AS `VALOR_MENOS_AJUSTE_TAR`,`fza_tarifas`.`FECHA_DESDE_DTO_TAR` AS `FECHA_DESDE_DTO_TAR`,`fza_tarifas`.`FECHA_HASTA_DTO_TAR` AS `FECHA_HASTA_DTO_TAR`,`fza_tarifas`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_tarifas`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_tarifas`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_tarifas`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_tarifas` where `fza_tarifas`.`ESACTIVO_ARTTAR` = 'S' order by `fza_tarifas`.`ORDEN_TAR`;

-- Vista: vi_usuarios
DROP TABLE IF EXISTS `vi_usuarios`;
DROP VIEW IF EXISTS `vi_usuarios`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_usuarios` AS select `fza_usuarios`.`USUARIO_USU` AS `USUARIO_USU`,`fza_usuarios`.`PASSWORD_USU` AS `PASSWORD_USU`,`fza_usuarios`.`GRUPO_USU` AS `GRUPO_USU`,`fza_usuarios`.`ESACTIVO_USU` AS `ESACTIVO_USU`,`fza_usuarios`.`EMPRESA_DEFECTO_USU` AS `EMPRESA_DEFECTO_USU`,`fza_usuarios`.`ULTIMO_LOGIN_USU` AS `ULTIMO_LOGIN_USU`,`fza_usuarios`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_usuarios`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_usuarios`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_usuarios`.`USUARIO_MODIF` AS `USUARIO_MODIF`,`fza_usuarios`.`ALMACEN_DEFECTO_USU` AS `ALMACEN_DEFECTO_USU`,`fza_usuarios`.`CAJA_DEFECTO_USU` AS `CAJA_DEFECTO_USU`,`vi_empresas`.`RAZON_SOCIAL_EMP` AS `RAZON_SOCIAL_EMP`,`fza_usuarios_grupos`.`GRUPO_USUGRP` AS `GRUPO_USUGRP`,`fza_usuarios_grupos`.`ESGRUPOADMINISTRADOR_USUGRP` AS `ESGRUPOADMINISTRADOR_USUGRP` from ((`fza_usuarios` join `fza_usuarios_grupos` on(`fza_usuarios`.`GRUPO_USU` = `fza_usuarios_grupos`.`GRUPO_USUGRP`)) left join `vi_empresas` on(`fza_usuarios`.`EMPRESA_DEFECTO_USU` = `vi_empresas`.`CODIGO_EMP_EMP`));

-- Vista: vi_usuarios_grupos
DROP TABLE IF EXISTS `vi_usuarios_grupos`;
DROP VIEW IF EXISTS `vi_usuarios_grupos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_usuarios_grupos` AS select `fza_usuarios_grupos`.`GRUPO_USUGRP` AS `GRUPO_USUGRP`,`fza_usuarios_grupos`.`ESGRUPOADMINISTRADOR_USUGRP` AS `ESGRUPOADMINISTRADOR_USUGRP`,`fza_usuarios_grupos`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_usuarios_grupos`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_usuarios_grupos`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_usuarios_grupos`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_usuarios_grupos`;

-- Vista: vi_usuarios_perfiles
DROP TABLE IF EXISTS `vi_usuarios_perfiles`;
DROP VIEW IF EXISTS `vi_usuarios_perfiles`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_usuarios_perfiles` AS select `fza_usuarios_perfiles`.`USUARIO_GRUPO_USUPER` AS `USUARIO_GRUPO_USUPER`,`fza_usuarios_perfiles`.`KEY_USUPER` AS `KEY_USUPER`,`fza_usuarios_perfiles`.`SUBKEY_USUPER` AS `SUBKEY_USUPER`,`fza_usuarios_perfiles`.`VALUE_USUPER` AS `VALUE_USUPER`,`fza_usuarios_perfiles`.`VALUE_TEXT_USUPER` AS `VALUE_TEXT_USUPER`,`fza_usuarios_perfiles`.`TYPE_BLOB_USUPER` AS `TYPE_BLOB_USUPER`,`fza_usuarios_perfiles`.`VALUE_BLOB_USUPER` AS `VALUE_BLOB_USUPER`,`fza_usuarios_perfiles`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_usuarios_perfiles`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_usuarios_perfiles`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_usuarios_perfiles`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_usuarios_perfiles`;

-- Vista: vi_variaciones
DROP TABLE IF EXISTS `vi_variaciones`;
DROP VIEW IF EXISTS `vi_variaciones`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vi_variaciones` AS select `fza_variaciones`.`CODIGO_VAR` AS `CODIGO_VAR`,`fza_variaciones`.`NOMBRE_VAR` AS `NOMBRE_VAR`,`fza_variaciones`.`ESACTIVO_VAR` AS `ESACTIVO_VAR`,`fza_variaciones`.`ORDEN_VAR` AS `ORDEN_VAR`,`fza_variaciones`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_variaciones`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_variaciones`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_variaciones`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_variaciones` order by `fza_variaciones`.`ORDEN_VAR`;

-- Vista: viest_temporada
DROP TABLE IF EXISTS `viest_temporada`;
DROP VIEW IF EXISTS `viest_temporada`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `viest_temporada` AS select `p`.`CODIGO_ART_ART` AS `CODIGO_ART`,`p`.`CODIGO_UNIDAD_ARTPROP` AS `CLAVE_NIVEL`,coalesce(`pv`.`PV`,`p`.`VALOR_LIBRE_ARTPROP`) AS `TEMPORADA` from (`fza_articulos_propiedades` `p` left join `fza_propiedades_valores` `pv` on(`pv`.`ID_PV_ARTPROP` = `p`.`ID_PV_ARTPROP`)) where `p`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA';

-- Vista: viest_temporadas
DROP TABLE IF EXISTS `viest_temporadas`;
DROP VIEW IF EXISTS `viest_temporadas`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `viest_temporadas` AS select distinct `viest_temporada`.`TEMPORADA` AS `TEMPORADA` from `viest_temporada` where `viest_temporada`.`TEMPORADA` is not null and `viest_temporada`.`TEMPORADA` <> '';

-- Vista: viest_ventas_dia
DROP TABLE IF EXISTS `viest_ventas_dia`;
DROP VIEW IF EXISTS `viest_ventas_dia`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `viest_ventas_dia` AS select `f`.`FECHA_FAC` AS `FECHA`,`l`.`CODIGO_ALM_FACLIN` AS `CODIGO_ALMACEN`,coalesce(`a`.`CODIGO_FAM_ART`,'') AS `CODIGO_FAMILIA`,coalesce(`tcol`.`TEMPORADA`,`tart`.`TEMPORADA`,'') AS `TEMPORADA`,count(0) AS `NUM_LINEAS_VENTA`,coalesce(sum(`l`.`CANTIDAD_FACLIN`),0) AS `UNIDADES_VENTA`,coalesce(sum(`l`.`TOTAL_FACLIN`),0) AS `IMPORTE_VENTA` from ((((`fza_facturas_lineas` `l` join `fza_facturas` `f` on(`f`.`NUMERO_FAC` = `l`.`NUMERO_FAC_FACLIN` and `f`.`SERIE_FAC` = `l`.`SERIE_FAC_FACLIN`)) left join `fza_articulos` `a` on(`a`.`CODIGO_ART_ART` = `l`.`CODIGO_ART_FACLIN`)) left join `viest_temporada` `tcol` on(`tcol`.`CODIGO_ART` = substring_index(`l`.`CODIGO_UNIDAD_FACLIN`,'/',1) and `tcol`.`CLAVE_NIVEL` = substring_index(`l`.`CODIGO_UNIDAD_FACLIN`,'/',2))) left join `viest_temporada` `tart` on(`tart`.`CODIGO_ART` = substring_index(`l`.`CODIGO_UNIDAD_FACLIN`,'/',1) and `tart`.`CLAVE_NIVEL` = '')) group by `f`.`FECHA_FAC`,`l`.`CODIGO_ALM_FACLIN`,coalesce(`a`.`CODIGO_FAM_ART`,''),coalesce(`tcol`.`TEMPORADA`,`tart`.`TEMPORADA`,'');

-- Vista: viest_movimientos_dia
DROP TABLE IF EXISTS `viest_movimientos_dia`;
DROP VIEW IF EXISTS `viest_movimientos_dia`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `viest_movimientos_dia` AS select cast(`m`.`FECHA_MOV` as date) AS `FECHA`,`m`.`CODIGO_ALM_MOV` AS `CODIGO_ALMACEN`,coalesce(`a`.`CODIGO_FAM_ART`,'') AS `CODIGO_FAMILIA`,coalesce(`tcol`.`TEMPORADA`,`tart`.`TEMPORADA`,'') AS `TEMPORADA`,count(0) AS `NUM_MOVIMIENTOS`,coalesce(sum(`m`.`CANTIDAD_MOV`),0) AS `UNIDADES_MOV`,coalesce(sum(`m`.`TOTAL_COSTE_MOV`),0) AS `COSTE_MOV` from ((((`fza_movimientos_almacen` `m` left join `fza_articulos_skus` `s` on(`s`.`CODIGO_UNIDAD_SKU` = `m`.`CODIGO_UNIDAD_MOV`)) left join `fza_articulos` `a` on(`a`.`CODIGO_ART_ART` = coalesce(`m`.`CODIGO_ART_MOV`,`s`.`CODIGO_ART_SKU`))) left join `viest_temporada` `tcol` on(`tcol`.`CODIGO_ART` = substring_index(`m`.`CODIGO_UNIDAD_MOV`,'/',1) and `tcol`.`CLAVE_NIVEL` = substring_index(`m`.`CODIGO_UNIDAD_MOV`,'/',2))) left join `viest_temporada` `tart` on(`tart`.`CODIGO_ART` = substring_index(`m`.`CODIGO_UNIDAD_MOV`,'/',1) and `tart`.`CLAVE_NIVEL` = '')) where `m`.`ESACTIVO_MOV` = 'S' group by cast(`m`.`FECHA_MOV` as date),`m`.`CODIGO_ALM_MOV`,coalesce(`a`.`CODIGO_FAM_ART`,''),coalesce(`tcol`.`TEMPORADA`,`tart`.`TEMPORADA`,'');

-- Vista: viest_dia
DROP TABLE IF EXISTS `viest_dia`;
DROP VIEW IF EXISTS `viest_dia`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `viest_dia` AS select `u`.`FECHA` AS `FECHA`,`u`.`CODIGO_ALMACEN` AS `CODIGO_ALMACEN`,`u`.`CODIGO_FAMILIA` AS `CODIGO_FAMILIA`,`u`.`TEMPORADA` AS `TEMPORADA`,sum(`u`.`NUM_MOVIMIENTOS`) AS `NUM_MOVIMIENTOS`,sum(`u`.`UNIDADES_MOV`) AS `UNIDADES_MOV`,sum(`u`.`COSTE_MOV`) AS `COSTE_MOV`,sum(`u`.`NUM_LINEAS_VENTA`) AS `NUM_LINEAS_VENTA`,sum(`u`.`UNIDADES_VENTA`) AS `UNIDADES_VENTA`,sum(`u`.`IMPORTE_VENTA`) AS `IMPORTE_VENTA` from (select `viest_movimientos_dia`.`FECHA` AS `FECHA`,`viest_movimientos_dia`.`CODIGO_ALMACEN` AS `CODIGO_ALMACEN`,`viest_movimientos_dia`.`CODIGO_FAMILIA` AS `CODIGO_FAMILIA`,`viest_movimientos_dia`.`TEMPORADA` AS `TEMPORADA`,`viest_movimientos_dia`.`NUM_MOVIMIENTOS` AS `NUM_MOVIMIENTOS`,`viest_movimientos_dia`.`UNIDADES_MOV` AS `UNIDADES_MOV`,`viest_movimientos_dia`.`COSTE_MOV` AS `COSTE_MOV`,0 AS `NUM_LINEAS_VENTA`,0 AS `UNIDADES_VENTA`,0 AS `IMPORTE_VENTA` from `viest_movimientos_dia` union all select `viest_ventas_dia`.`FECHA` AS `FECHA`,`viest_ventas_dia`.`CODIGO_ALMACEN` AS `CODIGO_ALMACEN`,`viest_ventas_dia`.`CODIGO_FAMILIA` AS `CODIGO_FAMILIA`,`viest_ventas_dia`.`TEMPORADA` AS `TEMPORADA`,0 AS `0`,0 AS `0`,0 AS `0`,`viest_ventas_dia`.`NUM_LINEAS_VENTA` AS `NUM_LINEAS_VENTA`,`viest_ventas_dia`.`UNIDADES_VENTA` AS `UNIDADES_VENTA`,`viest_ventas_dia`.`IMPORTE_VENTA` AS `IMPORTE_VENTA` from `viest_ventas_dia`) `u` group by `u`.`FECHA`,`u`.`CODIGO_ALMACEN`,`u`.`CODIGO_FAMILIA`,`u`.`TEMPORADA`;

